const PROGRESS_KEY='liam-progress',PROGRESS_SCHEMA_VERSION=2,STUDENT={name:'Liam DeVries',grade:9};
let saved={};
function nowStamp(){return new Date().toISOString().replace(/[:.]/g,'-')}
function backupRawProgress(reason,raw){try{if(raw)localStorage.setItem(`${PROGRESS_KEY}-backup-${nowStamp()}`,JSON.stringify({reason,createdAt:new Date().toISOString(),raw}))}catch(e){}}
function migrateProgress(record){let next=record&&typeof record==='object'?record:{};if(next.__schemaVersion===PROGRESS_SCHEMA_VERSION)return next;let raw='';try{raw=localStorage.getItem(PROGRESS_KEY)||''}catch(e){}backupRawProgress('automatic schema migration',raw);next={...next,__schemaVersion:PROGRESS_SCHEMA_VERSION,__student:STUDENT,__migratedAt:new Date().toISOString(),__schemaHistory:[...(next.__schemaHistory||[]),{from:next.__schemaVersion||1,to:PROGRESS_SCHEMA_VERSION,at:new Date().toISOString()}]};return next}
function loadProgress(){try{let raw=localStorage.getItem(PROGRESS_KEY);if(!raw)return migrateProgress({});let parsed=JSON.parse(raw);return migrateProgress(parsed)}catch(e){try{let raw=localStorage.getItem(PROGRESS_KEY)||'';backupRawProgress('unreadable progress preserved',raw)}catch(_){}return migrateProgress({__loadError:String(e&&e.message||e)})}}
saved=loadProgress();
const TERM_DEFS={
biology:{
biology:['The study of life and living things.','A biologist studies organisms, cells, ecosystems, heredity, evolution, and how living systems work.'],
organism:['A living thing that has all the characteristics of life.','A bacterium, oak tree, mushroom, dog, and human are all organisms.'],
organization:['The orderly structure of living things, from cells to tissues, organs, organ systems, organisms, populations, and ecosystems.','A heart cell, heart tissue, the heart, and the circulatory system show biological organization.'],
reproduction:['The process by which living things produce offspring.','Bacteria dividing and flowering plants making seeds are examples of reproduction.'],
species:['A group of similar organisms that can breed and produce fertile offspring in nature.','Different bird species may live in the same forest but reproduce within their own species.'],
growth:['An increase in living material or body size.','A seedling growing into a mature plant shows growth.'],
development:['The changes an organism goes through during its life.','A tadpole becoming a frog is development.'],
environment:['An organism’s surroundings, including living and nonliving factors.','Temperature, water, food, predators, and shelter are parts of an organism’s environment.'],
stimulus:['A change in an organism’s surroundings that causes a response.','Bright light can be a stimulus that causes pupils to get smaller.'],
response:['A reaction to a stimulus.','A plant bending toward light is a response.'],
homeostasis:['The regulation of stable internal conditions needed for survival.','Sweating helps the body maintain temperature homeostasis.'],
energy:['The ability to cause change or do work.','Cells use energy from food to build molecules, move materials, and grow.'],
hypothesis:['A testable possible explanation for an observation or question.','If moss grows better in shade, a scientist might hypothesize that lower light helps moss stay moist.'],
experiment:['A planned test used to collect evidence about a question or hypothesis.','A moss experiment could compare moss growth in shady and sunny conditions while keeping soil and water similar.'],
variable:['A factor in an experiment that can change or be measured.','In a moss investigation, light level could be the changed variable and moss growth could be the measured variable.'],
'independent variable':['The factor a scientist deliberately changes in an experiment.','Changing the amount of light a plant receives makes light the independent variable.'],
'dependent variable':['The factor a scientist measures to see the result of the change.','Measuring how much moss grows makes moss growth the dependent variable.'],
control:['A comparison setup or unchanged condition used to judge experimental results.','Keeping the same soil and water helps make a moss investigation fair.'],
'quantitative data':['Information that uses numbers, counts, or measurements.','The leaf is 8 cm long and the plant has 12 leaves are quantitative data.'],
'qualitative data':['Information that describes qualities or characteristics.','The flower is bright yellow and the stem feels rough are qualitative data.'],
adaptation:['An inherited structure, behavior, or process that helps an organism survive and reproduce.','Camouflage can be an adaptation that helps an animal avoid predators.'],
evolution:['Change in inherited traits of populations over generations.','A population becoming better suited to its environment over many generations is evolution.'],
cell:['The basic unit of structure and function in living things.','A single bacterium is one cell; plants and animals are made of many cells.'],
ecology:['The study of interactions among organisms and between organisms and their environments.','Ecology explains how wolves, deer, plants, water, and climate affect one another.'],
ecosystem:['A community of organisms and the nonliving environment they interact with.','A pond ecosystem includes fish, algae, water, sunlight, and minerals.'],
'abiotic factor':['A nonliving part of the environment that affects organisms.','Sunlight, temperature, water, and soil are abiotic factors.'],
'biotic factor':['A living or once-living part of the environment.','Plants, animals, fungi, and bacteria are biotic factors.'],
population:['All members of the same species living in the same area at the same time.','All the deer in one forest make up a deer population.'],
community:['All the populations of different species living and interacting in an area.','Trees, birds, insects, fungi, and mammals in a forest form a community.'],
DNA:['The genetic material that carries instructions for life processes.','DNA contains instructions for traits such as some eye colors or plant characteristics.'],
habitat:['The place where an organism lives and gets what it needs to survive.','A barn owl may live in grasslands, fields, and barns. That place is its habitat.'],
niche:['An organism’s role in its ecosystem, including how it gets food, uses resources, and interacts with other organisms.','A barn owl’s niche includes hunting mice at night and helping control small mammal populations.'],
symbiosis:['A close relationship between organisms of different species in which at least one organism benefits.','Ticks on deer, orchids growing on trees, and ants protecting acacia trees are symbiotic relationships.'],
mutualism:['A symbiotic relationship in which both organisms benefit.','Ants get shelter and food from an acacia tree, while the ants help protect the tree.'],
commensalism:['A symbiotic relationship in which one organism benefits and the other is not helped or harmed much.','An orchid growing on a tree gets a place to live while the tree is mostly unaffected.'],
parasitism:['A symbiotic relationship in which one organism benefits and the host is harmed.','A tick feeding on a deer benefits, while the deer loses blood and may be irritated or sick.'],
producer:['An organism that makes its own food, usually using sunlight.','Grass is a producer because it uses sunlight to make sugars.'],
autotroph:['An organism that makes its own nutrients from nonliving sources such as sunlight or chemicals.','Plants and many algae are autotrophs.'],
heterotroph:['An organism that gets energy by consuming other organisms or organic matter.','Rabbits, hawks, fungi, and humans are heterotrophs.'],
consumer:['An organism that gets energy by eating producers or other consumers.','A rabbit that eats grass and a hawk that eats a snake are consumers.'],
herbivore:['A consumer that eats plants or other producers.','A rabbit eating grass is a herbivore.'],
carnivore:['A consumer that eats animals.','A hawk that eats a snake is a carnivore.'],
omnivore:['A consumer that eats both plants and animals.','A bear that eats berries and fish is an omnivore.'],
scavenger:['A consumer that eats dead organisms.','A vulture feeding on a dead animal is a scavenger.'],
decomposer:['An organism that breaks down dead matter and returns nutrients to the ecosystem.','Fungi and bacteria decomposing leaves help recycle matter.'],
'food chain':['A simple pathway showing how energy and matter move from one organism to another.','Sun -> grass -> grasshopper -> frog shows one food chain.'],
'food web':['A network of connected food chains showing many feeding relationships in an ecosystem.','A hawk might eat mice, rabbits, frogs, and snakes, so it belongs in a food web.'],
'trophic level':['A feeding step in a food chain or energy pyramid.','Producers are the first trophic level; herbivores are usually the next level.'],
matter:['The material that makes up living and nonliving things.','Water, carbon, nitrogen, and phosphorus are matter that cycles through ecosystems.']
},
geography:{
geography:['The study of Earth’s physical features, living things, places, and how people interact with environments.','Geography explains where things are, why they are there, and how places are connected.'],
location:['The position of a place on Earth.','A school can be described by its street address, coordinates, or nearby landmarks.'],
'absolute location':['The exact position of a place, often described with latitude and longitude.','Dallas is near 32°N, 96°W.'],
'relative location':['Where a place is in relation to other places.','New Orleans is south of Baton Rouge and near the mouth of the Mississippi River.'],
hemisphere:['One half of Earth, such as Northern, Southern, Eastern, or Western Hemisphere.','The Equator divides Earth into Northern and Southern Hemispheres.'],
'grid system':['A network of latitude and longitude lines used to locate places.','A map grid helps identify a city’s exact position.'],
latitude:['Distance north or south of the Equator, measured in degrees.','A place at 30°N is north of the Equator.'],
longitude:['Distance east or west of the Prime Meridian, measured in degrees.','A place at 90°W is west of the Prime Meridian.'],
place:['A location with physical and human characteristics that make it meaningful.','A desert city has climate, landforms, buildings, roads, and cultural features.'],
region:['An area with shared physical or human characteristics.','The Midwest is a region often connected with farming and certain climate patterns.'],
'formal region':['A region defined by a common measurable trait.','A state, country, or climate zone can be a formal region.'],
'functional region':['A region organized around a central point and its connections.','A city and its suburbs can form a functional region.'],
'perceptual region':['A region based on people’s feelings or ideas about a place.','“The South” can be a perceptual region.'],
ecosystem:['A community of living things and the nonliving environment they depend on.','A coral reef ecosystem includes coral, fish, sunlight, water, and minerals.'],
movement:['The flow of people, goods, ideas, or information from place to place.','Trade routes and migration are examples of movement.'],
'human-environment interaction':['The ways people use, adapt to, and change the environment.','Irrigation, farming, roads, and dams are human-environment interactions.'],
'physical geography':['The study of Earth’s natural features and physical systems.','Mountains, rivers, climate, and vegetation are part of physical geography.'],
'human geography':['The study of people, cultures, economies, settlements, and movement across Earth.','Population density and migration are human geography topics.'],
hydrosphere:['All of Earth’s water, including oceans, rivers, lakes, ice, and water vapor.','The Pacific Ocean and polar ice are parts of the hydrosphere.'],
lithosphere:['Earth’s land and rocky outer layer.','Continents, ocean floors, and mountains are part of the lithosphere.'],
atmosphere:['The layer of gases surrounding Earth.','Weather happens in the lower atmosphere.'],
biosphere:['The part of Earth where life exists.','Forests, oceans, grasslands, and soil ecosystems are parts of the biosphere.'],
crust:['Earth’s thin, rocky outer layer.','Continents and ocean floors are part of the crust.'],
mantle:['The thick layer of hot rock beneath Earth’s crust.','Slow movement in the mantle helps move tectonic plates.'],
core:['Earth’s hot, dense center.','The core lies beneath the mantle.'],
'continental drift':['The idea that continents have slowly moved over Earth’s surface over geologic time.','Matching coastlines and fossils helped scientists think continents were once connected.'],
magma:['Melted rock beneath Earth’s surface.','Magma can rise and feed a volcano.'],
'plate tectonics':['The theory that Earth’s crust is broken into moving plates that shape landforms and oceans.','Plate movement can build mountains, cause earthquakes, and create volcanoes.'],
subduction:['A plate interaction where one plate sinks beneath another plate.','Subduction can create volcanoes and deep ocean trenches.'],
accretion:['The process of material being added to the edge of a landmass.','Sediment or crustal fragments can be added to a continent by accretion.'],
spreading:['A plate interaction where plates move apart and new crust forms.','Seafloor spreading occurs where ocean plates pull apart.'],
fold:['A bend in rock layers caused by pressure.','Folded rock layers can help form mountains.'],
fault:['A break in rock where movement occurs.','Earthquakes often happen along faults.'],
earthquake:['A sudden shaking of Earth’s crust caused by movement along a fault.','Stress from moving plates can be released as an earthquake.'],
volcano:['An opening in Earth’s crust where magma, ash, and gases can reach the surface.','A volcanic island can form when lava builds up above sea level.'],
weathering:['The process that breaks rock into smaller pieces without moving it far away.','Water freezing in cracks can cause weathering.'],
erosion:['The movement of weathered material by water, wind, ice, or gravity.','A river carrying sediment downstream is erosion.'],
loess:['Fine soil deposited by wind.','Windblown loess can create fertile soil in some regions.'],
glacier:['A large, slow-moving mass of ice.','Glaciers can carve valleys and move rock material.'],
moraine:['A ridge or pile of rock material left by a glacier.','A moraine can mark where a glacier once stopped.'],
'water cycle':['The continuous movement of water through evaporation, condensation, precipitation, runoff, and groundwater.','Water evaporates from the ocean, forms clouds, falls as rain, and returns to rivers or the sea.'],
evaporation:['The change of liquid water into water vapor.','Sunlight can cause ocean water to evaporate.'],
condensation:['The change of water vapor into liquid droplets.','Condensation forms clouds.'],
precipitation:['Water that falls from clouds as rain, snow, sleet, or hail.','Rain falling on mountains is precipitation.'],
desalination:['The process of removing salt from seawater.','Desalination can make ocean water usable, but it often requires energy and equipment.'],
groundwater:['Water stored beneath Earth’s surface in soil and rock spaces.','Wells often draw groundwater.'],
aquifer:['An underground layer of rock or sediment that stores and carries groundwater.','A community may use an aquifer as a freshwater source.'],
freshwater:['Water with very little salt, found in rivers, lakes, ice, and underground.','Freshwater is limited but essential for drinking, farming, and ecosystems.'],
'salt water':['Water containing a high amount of dissolved salts.','Most ocean water is salt water and cannot be drunk without treatment.'],
runoff:['Water that flows over land into streams, rivers, lakes, or oceans.','After heavy rain, runoff can carry sediment down a slope.']
}
};
TERM_DEFS.math={
equation:['A mathematical statement showing that two expressions are equal.','In 3x + 5 = 20, both sides must stay balanced while solving.'],
solution:['A value that makes an equation or inequality true.','x = 5 is the solution of 3x + 5 = 20.'],
variable:['A letter or symbol that represents a number.','In 4x - 7, x is the variable.'],
inequality:['A statement that compares quantities using symbols such as <, >, <=, or >=.','x > 4 means x can be any number greater than 4.'],
function:['A relationship where each input has exactly one output.','If x = 2 always gives y = 7, that input has one output.'],
slope:['The rate of change of a line, often rise divided by run.','A slope of 2 means y rises 2 for every 1 step right.'],
'y-intercept':['The point where a graph crosses the y-axis.','In y = 2x + 5, the y-intercept is 5.'],
'system of equations':['Two or more equations considered together.','The solution is the point that satisfies both equations.'],
'exponential function':['A function with a constant ratio or percent-change pattern.','y = 3(2)^x doubles each time x increases by 1.'],
mean:['The sum of data values divided by the number of values.','The mean of 4, 6, and 8 is 6.'],
median:['The middle value when data are ordered.','For 2, 7, 9, the median is 7.'],
theorem:['A statement that has been proven true.','Theorems are justified by definitions, postulates, and prior theorems.'],
congruence:['Having the same size and shape.','Congruent figures can be moved by rigid transformations to match.']
};
const WEEK2_GUIDES={
biology:{2:{title:'Week 2 Biology Day: Principles of Ecology',big:'An ecosystem is a connected system where living things interact with each other and with nonliving conditions. Energy moves through feeding relationships while matter is recycled.',mastery:['biotic vs abiotic','organism -> population -> community -> ecosystem','habitat vs niche','mutualism, commensalism, and parasitism','producer, consumer, herbivore, carnivore, omnivore, scavenger, decomposer','food-chain arrows show the direction energy and matter move'],steps:[
{t:'Ecosystems: living and nonliving parts',k:'biotic factor, abiotic factor, ecosystem',v:'pond',learn:'Ecology studies interactions among organisms and between organisms and their environment. An ecosystem includes living parts, called biotic factors, and nonliving conditions, called abiotic factors. In a pond, fish, algae, insects, and bacteria are biotic. Water, rocks, sunlight, temperature, and dissolved oxygen are abiotic. Both kinds of factors matter because a change in one part of the system can affect the others.',see:['Fish, algae, insects, bacteria','Water, rocks, sunlight, temperature'],sort:{id:'biotic-abiotic-pond',prompt:'Sort these pond parts into the correct group.',groups:[{id:'biotic',label:'BIOTIC',description:'Living parts of the ecosystem'},{id:'abiotic',label:'ABIOTIC',description:'Nonliving parts of the ecosystem'}],items:[{id:'fish',label:'fish',correctGroupId:'biotic'},{id:'algae',label:'algae',correctGroupId:'biotic'},{id:'insects',label:'insects',correctGroupId:'biotic'},{id:'water',label:'water',correctGroupId:'abiotic'},{id:'rocks',label:'rocks',correctGroupId:'abiotic'},{id:'sunlight',label:'sunlight',correctGroupId:'abiotic'},{id:'dissolved-oxygen',label:'dissolved oxygen',correctGroupId:'abiotic'}]},apply:'If the pond water temperature rises, is that a biotic or abiotic change? How could it affect fish or algae?',more:'A pond is not just a list of organisms. It is a set of relationships: sunlight affects algae, algae affect oxygen, oxygen affects fish, and bacteria recycle matter.'},
{t:'Levels of ecological organization',k:'organism, population, community, ecosystem',v:'ladder',learn:'Ecologists describe living systems at different levels. One living thing is an organism. A group of the same species in one area is a population. All the different populations interacting in one area form a community. A community plus the nonliving environment is an ecosystem. The order matters because each level adds more relationships.',see:['One coyote','Coyotes in a valley','Coyotes, rabbits, grasses, hawks','Living community plus soil, water, temperature'],sequence:{id:'ecological-organization-sequence',prompt:'Put these in order from smallest to largest.',items:[{id:'organism',label:'organism',order:1},{id:'population',label:'population',order:2},{id:'community',label:'community',order:3},{id:'ecosystem',label:'ecosystem',order:4}]},apply:'A group of coyotes living in one valley is which level? What level includes coyotes, rabbits, grasses, hawks, soil, water, and temperature?',more:'A biological community does not include rocks, soil, water, or sunlight. Once abiotic factors are included, you are describing an ecosystem.'},
{t:'Habitat and niche',k:'habitat, niche',v:'two',learn:'Habitat means where an organism lives. Niche means how an organism lives there: how it gets food, what resources it uses, when it is active, and how it interacts with other organisms. A barn owl may have a habitat of grasslands, fields, and barns. Its niche includes hunting mice at night and nesting in quiet sheltered places.',see:['Habitat: where it lives','Niche: how it survives and interacts'],try:'Classify the statement: “A barn owl hunts mice at night.”',choices:[['Habitat',0,'That describes what the owl does and how it gets food, so it is niche.'],['Niche',1,'Right. Hunting mice at night describes the owl’s role and behavior in the ecosystem.']],apply:'Write one habitat statement and one niche statement for a frog, owl, or rabbit.',more:'Two species can share a habitat but not have the exact same niche. Different niches reduce direct competition.'},
{t:'Symbiosis: three close relationships',k:'symbiosis, mutualism, commensalism, parasitism',v:'symbiosis',learn:'Symbiosis is a close relationship between organisms of different species. In mutualism, both organisms benefit. In commensalism, one benefits and the other is not helped or harmed much. In parasitism, one benefits while the host is harmed. The key is to identify what happens to each organism.',see:['Mutualism: + / +','Commensalism: + / 0','Parasitism: + / -'],try:'A tick feeds on a deer. Which relationship is this?',choices:[['Mutualism',0,'Both organisms do not benefit. The deer is harmed.'],['Commensalism',0,'The deer is affected, so this is not commensalism.'],['Parasitism',1,'Correct. The tick benefits and the deer is harmed.']],apply:'Choose one example: ants and acacia, orchid on a tree, or tick on deer. Explain who benefits and who is harmed or unaffected.',more:'Do not memorize only examples. Ask: who benefits, who is harmed, and who is unaffected?'},
{t:'Energy roles in ecosystems',k:'producer, autotroph, heterotroph, consumer, herbivore, carnivore, omnivore, scavenger, decomposer',v:'roles',learn:'Producers, also called autotrophs, make their own nutrients, usually using sunlight. Consumers, also called heterotrophs, get energy by eating other organisms or organic matter. Herbivores eat producers, carnivores eat animals, omnivores eat both, scavengers eat dead organisms, and decomposers break down dead matter and recycle nutrients.',see:['Grass: producer','Rabbit: herbivore','Hawk: carnivore','Bear: omnivore','Vulture: scavenger','Fungus: decomposer'],try:'Which role best fits fungus breaking down dead leaves?',choices:[['Producer',0,'A producer makes its own food. Fungus gets energy from dead matter.'],['Decomposer',1,'Correct. Decomposers break down dead matter and return nutrients.'],['Herbivore',0,'A herbivore eats producers; decomposers break down dead material.']],apply:'Classify grass, rabbit, hawk, bear, vulture, and fungus by energy role.',more:'Decomposers are not optional cleanup workers. Without them, matter would remain locked in dead organisms and waste.'},
{t:'Food chains and arrow direction',k:'food chain, producer, consumer, energy, matter',v:'chain',learn:'A food chain shows one pathway for energy and matter in an ecosystem. The arrow points in the direction energy and matter move. In Sun -> grass -> grasshopper -> frog -> snake -> hawk, grass is the producer and the grasshopper is a consumer. The arrow from grasshopper to frog means energy and matter move from the grasshopper to the frog when the frog eats it.',see:['Sun','Grass','Grasshopper','Frog','Snake','Hawk'],try:'What does grasshopper -> frog mean?',choices:[['The grasshopper eats the frog.',0,'Follow the arrow direction: energy and matter move from grasshopper to frog.'],['Energy and matter move from grasshopper to frog.',1,'Yes. The frog gets energy and matter by eating the grasshopper.'],['The frog gives energy back to the grasshopper.',0,'That reverses the arrow.']],apply:'In grass -> rabbit -> fox, identify the producer and explain what happens if rabbits decrease sharply.',more:'Food-chain arrows are one of the easiest places to get mixed up. Always ask: where does energy go next?'},
{t:'Food webs are more realistic',k:'food web, food chain, ecosystem',v:'web',learn:'A food chain shows one pathway, but most organisms have more than one feeding relationship. A food web shows connected food chains. A hawk might eat a mouse, rabbit, frog, or snake. If one population changes, several other populations may be affected because the web has many connections.',see:['Grass and seeds','Grasshopper, rabbit, mouse','Frog, snake','Hawk'],try:'Why is a food web usually more realistic than one food chain?',choices:[['It shows many connected feeding relationships.',1,'Correct. Ecosystems usually have multiple feeding paths.'],['It always has fewer organisms.',0,'A web usually shows more relationships, not fewer.']],apply:'Pick one organism in a garden food web and describe two feeding connections it could have.',more:'Food webs help explain why ecosystem changes can spread in more than one direction.'},
{t:'Trophic levels and energy pyramids',k:'trophic level, producer, consumer, energy',v:'pyramid',learn:'A trophic level is a feeding step. Producers form the base because they bring energy into the living part of the ecosystem. Consumers occupy higher levels. As energy moves from one level to the next, much of it is changed to heat, so less usable energy is available at higher levels. That is why energy pyramids have a wide base and narrow top.',see:['Hawk','Snake','Rabbit','Grass'],try:'Why are producers at the base of an energy pyramid?',choices:[['They are the smallest organisms.',0,'Size is not the reason. Producers bring energy into the food system.'],['They support the energy needs of higher levels.',1,'Correct. Producers are the energy base for consumers.']],apply:'Explain why there are usually fewer top predators than producers.',more:'No math is needed here. The important idea is that usable energy decreases as it moves upward.'},
{t:'Energy flows, matter cycles',k:'energy, matter, decomposer',v:'cycle',learn:'Energy and matter behave differently in ecosystems. Energy flows through feeding relationships and is eventually lost as heat. Matter cycles. Water, carbon, nitrogen, and phosphorus are reused as organisms live, die, decompose, and become part of the environment again. Decomposers are important because they return matter to the ecosystem.',see:['Energy: one-way flow','Matter: recycled through living and nonliving parts'],try:'Which statement is correct?',choices:[['Energy cycles forever in the same way matter does.',0,'Energy flows and is lost as heat. Matter cycles.'],['Energy flows through ecosystems; matter cycles through ecosystems.',1,'Yes. That is the core idea.']],apply:'Write one sentence explaining why decomposers matter in the cycling of matter.',more:'A strong ecology answer often separates these two ideas: energy flows, matter cycles.'},
{t:'Ecosystem detective',k:'ecosystem, biotic factor, abiotic factor, producer, consumer, decomposer, food chain',v:'detective',learn:'Now use the whole chapter idea. A backyard garden includes tomato plants, bees, caterpillars, birds, earthworms, fungi, soil, water, sunlight, and air. You can describe it as an ecosystem by identifying living and nonliving parts, energy roles, feeding relationships, and what might change if one factor changes.',see:['Tomato plants','Bees and caterpillars','Birds','Earthworms and fungi','Soil, water, sunlight, air'],try:'Build a garden explanation with at least 3 biotic factors, 3 abiotic factors, 1 producer, 2 consumers, 1 decomposer, and one food chain.',evidence:true,apply:'If caterpillars fall sharply, predict one possible effect on birds and explain your evidence.',more:'Tiny changes in an ecosystem can ripple through several relationships. A change in one food source may affect organisms that eat it, organisms that compete with it, and the plants or materials it uses. That is why ecologists look for connections instead of studying each organism as if it were alone.'},
{t:'Biology mastery check',k:'biotic factor, abiotic factor, habitat, niche, symbiosis, producer, food chain, food web, matter',v:'mastery',learn:'Use this check to show enough understanding. Aim for solid reasoning, not perfection. If one idea is shaky, review that concept and try a simpler example.',questions:['Classify rainfall as biotic or abiotic and explain why.','Put these in order: community, organism, ecosystem, population.','Is “where a rabbit lives” habitat or niche?','Is “a rabbit eats grass and hides in brush” habitat or niche?','A bee pollinates a flower while getting nectar. Which symbiosis type is this?','In grass -> rabbit -> fox, what does the arrow from rabbit to fox mean?','Why is a food web more realistic than one food chain?','What is the difference between energy flow and matter cycling?'],apply:'Write the chapter idea in your own words: an ecosystem is connected because...',more:'A successful answer should include living factors, nonliving factors, feeding relationships, energy flow, and matter cycling.'}
]}},
geography:{2:{title:'Week 2 World Geography Day: The Earth',big:'Earth is made of interacting systems. Internal forces such as plate movement and external forces such as weathering and erosion reshape the planet, while water moves through Earth in a cycle.',mastery:['hydrosphere, lithosphere, atmosphere, biosphere','core, mantle, crust','plate tectonics','internal vs external forces','weathering vs erosion','water cycle sequence','freshwater, groundwater, aquifers'],steps:[
{t:'Earth as four connected spheres',k:'hydrosphere, lithosphere, atmosphere, biosphere',v:'earth',learn:'Geographers study Earth as a system of interacting parts. The hydrosphere is Earth’s water. The lithosphere is land and rock. The atmosphere is the layer of gases around Earth. The biosphere is where life exists. These spheres interact constantly: rain falls through air, lands on rock, flows into streams, and supports plants and animals.',see:['Hydrosphere: water','Lithosphere: land and rock','Atmosphere: air','Biosphere: life'],sort:{id:'earth-spheres-sort',prompt:'Sort each example into the correct Earth sphere.',groups:[{id:'hydrosphere',label:'HYDROSPHERE',description:'Earth water'},{id:'lithosphere',label:'LITHOSPHERE',description:'Land and rock'},{id:'atmosphere',label:'ATMOSPHERE',description:'Air and gases'},{id:'biosphere',label:'BIOSPHERE',description:'Life'}],items:[{id:'pacific-ocean',label:'Pacific Ocean',correctGroupId:'hydrosphere'},{id:'mountain',label:'mountain',correctGroupId:'lithosphere'},{id:'cloud-air',label:'cloud-bearing air',correctGroupId:'atmosphere'},{id:'forest-life',label:'forest life',correctGroupId:'biosphere'}]},apply:'Rain falls on a mountain, plants absorb water, and streams flow downslope. Which spheres are interacting?',more:'The main point is connection. Geography often asks how physical systems work together across places.'},
{t:'Inside Earth',k:'crust, mantle, core',v:'layers',learn:'Earth has internal layers. The crust is the thin rocky outer layer. Beneath it is the mantle, a thick layer of hot rock that can move slowly over long periods. The core is Earth’s hot, dense center. These layers matter because movement inside Earth helps shape the surface.',see:['Crust: thin outside','Mantle: thick hot rock','Core: hot dense center'],try:'Which layer is the thin rocky outer layer?',choices:[['Crust',1,'Correct. The crust is Earth’s outer rocky layer.'],['Mantle',0,'The mantle is below the crust.'],['Core',0,'The core is Earth’s center.']],apply:'Why does it matter that Earth has active layers beneath the surface?',more:'Do not worry about exact depths today. Know the order and the role each layer plays.'},
{t:'Plate tectonics',k:'plate tectonics, continental drift',v:'plates',learn:'Earth’s crust is broken into large moving plates. Plate tectonics explains how these plates move and shape continents, ocean basins, mountains, earthquakes, and volcanoes. Continental drift was an earlier idea that continents had moved over time; plate tectonics explains the mechanism better.',see:['Plate A moves slowly','Plate B moves slowly','Boundary changes surface features'],try:'What can moving plates create or cause?',choices:[['Mountains, earthquakes, volcanoes, and ocean features',1,'Yes. Plate movement is an internal force shaping Earth.'],['Only weather and clouds',0,'Weather is atmosphere-related. Plate movement shapes land and ocean basins.']],apply:'Explain how slow plate movement can still create major landforms over time.',more:'Plate movement is slow compared with a human life, but over geologic time it can reshape continents.'},
{t:'Plate interactions',k:'subduction, accretion, spreading',v:'boundary',learn:'Plates can interact in different ways. In subduction, one plate sinks beneath another. In accretion, material is added to the edge of a landmass. In spreading, plates move apart and new crust forms. Each interaction changes Earth’s surface differently.',see:['Subduction: one sinks','Accretion: material added','Spreading: plates separate'],try:'Which word matches “plates move apart and new crust forms”?',choices:[['Subduction',0,'Subduction means one plate sinks beneath another.'],['Spreading',1,'Correct. Spreading occurs where plates move apart.'],['Accretion',0,'Accretion means material is added to a landmass.']],apply:'Choose subduction, accretion, or spreading and describe one landform or feature it could help create.',more:'A boundary is not just a line on a map. It is a place where plate movement can build, break, or recycle crust.'},
{t:'Folds, faults, earthquakes, and volcanoes',k:'fold, fault, earthquake, volcano, magma',v:'fault',learn:'Pressure inside Earth can bend rock layers into folds or break them along faults. When rock moves suddenly along a fault, an earthquake can occur. Volcanoes form where magma reaches or nears the surface. These are internal forces because they come from energy and movement inside Earth.',see:['Fold: bent rock','Fault: broken rock with movement','Earthquake: sudden shaking','Volcano: magma reaches surface'],try:'A crack in rock where movement occurs is a...',choices:[['Fold',0,'A fold is bent rock.'],['Fault',1,'Correct. A fault is a break where movement occurs.'],['Glacier',0,'A glacier is moving ice, an external surface force.']],apply:'Write a cause/effect chain: plate movement -> stress builds -> movement along fault -> ...',more:'Internal forces can be sudden, like earthquakes, or slow, like mountain building.'},
{t:'External forces: weathering and erosion',k:'weathering, erosion, loess, glacier, moraine',v:'weathering',learn:'External forces work on Earth’s surface. Weathering breaks rock down. Erosion moves weathered material by water, wind, ice, or gravity. A freeze crack in rock is weathering. A river carrying sediment downstream is erosion. Wind can deposit loess, and glaciers can move material and leave moraines.',see:['Weathering: breaks rock','Erosion: moves sediment','Deposition: leaves material behind'],try:'A river carries sediment away from a cliff. Is that weathering or erosion?',choices:[['Weathering',0,'Weathering breaks material down. Carrying it away is erosion.'],['Erosion',1,'Correct. Movement of weathered material is erosion.']],apply:'Classify river valley, wind-blown sediment, glacier-carved land, and volcanic island as internal, external, or both.',more:'The quick test: breaking apart = weathering; carrying away = erosion.'},
{t:'What shaped this landform?',k:'internal forces, external forces, volcano, erosion, glacier',v:'landform',learn:'Many landforms are shaped by more than one process. A mountain range may begin through internal forces, then weathering and erosion change its surface. A volcanic island forms through internal forces, then waves, rain, and wind reshape it. Good geography explanations often include both origin and later change.',see:['Mountain range','Volcanic island','River valley','Glacier valley'],try:'A volcanic island with steep slopes and streams carrying sediment is shaped by...',choices:[['Only internal forces',0,'The volcano is internal, but streams carrying sediment are external erosion.'],['Internal and external forces',1,'Correct. Volcanism builds it; water and erosion reshape it.']],apply:'Pick one landform and explain what shaped it using internal/external evidence.',more:'Do not stop at naming a landform. Explain the process that created or changed it.'},
{t:'Earth’s water',k:'hydrosphere, freshwater, salt water, desalination',v:'water',learn:'About 70 percent of Earth’s surface is covered by water, but most of that water is salt water. Freshwater is limited and extremely important for people, farming, ecosystems, and cities. Desalination can remove salt from seawater, but it takes resources and is not the default solution everywhere.',see:['Most water: oceans','Limited freshwater','People and ecosystems depend on freshwater'],try:'Why is freshwater considered limited even though Earth has so much water?',choices:[['Because most water is salt water or not easy to use.',1,'Correct. The amount of usable freshwater is limited.'],['Because oceans are usually dry.',0,'Oceans hold most of Earth’s water, but it is salt water.']],apply:'Explain why a city planner must think carefully about freshwater supply.',more:'A water-rich planet can still have freshwater scarcity because location, salt, ice, pollution, and access matter.'},
{t:'The water cycle',k:'water cycle, evaporation, condensation, precipitation, runoff, groundwater',v:'cycle',learn:'The water cycle is the movement of water through Earth’s systems. Evaporation changes liquid water into vapor. Condensation forms clouds. Precipitation returns water to Earth as rain, snow, sleet, or hail. Water may collect, run off into rivers, soak into the ground as groundwater, or evaporate again.',see:['Evaporation','Condensation','Precipitation','Runoff / groundwater','Evaporation again'],sequence:{id:'water-cycle-sequence',prompt:'Put these water cycle steps in order.',items:[{id:'evaporation',label:'evaporation',order:1},{id:'condensation',label:'condensation',order:2},{id:'precipitation',label:'precipitation',order:3}]},apply:'Trace one drop of ocean water through clouds, rain, a stream, and back toward the ocean.',more:'The water cycle links hydrosphere, atmosphere, lithosphere, and biosphere.'},
{t:'Groundwater and aquifers',k:'groundwater, aquifer, freshwater',v:'aquifer',learn:'Some water soaks into the ground and becomes groundwater. An aquifer is an underground layer of rock or sediment that stores and carries groundwater. Aquifers matter because people may use them for drinking water, farming, and communities. If groundwater is used faster than it is replaced, future supply can become a problem.',see:['Rain soaks down','Groundwater fills spaces','Aquifer stores and carries water','Well draws water'],try:'What is an aquifer?',choices:[['An underground layer that stores and carries groundwater',1,'Correct. Aquifers can be important freshwater sources.'],['A cloud that makes rain',0,'Clouds are part of condensation and precipitation, not aquifers.']],apply:'Why might a town protect land above an aquifer?',more:'Groundwater is hidden, but it is still part of the hydrosphere and water cycle.'},
{t:'Earth system challenge',k:'volcano, hydrosphere, lithosphere, biosphere, weathering, erosion',v:'challenge',learn:'Use the chapter ideas together. A volcanic island has steep mountains. Heavy rain falls. Streams carry sediment to the coast. Plants grow on the slopes. This situation includes Earth spheres, internal forces, external forces, and system interactions.',try:'Identify one internal force, one external force, one hydrosphere example, one lithosphere example, one biosphere example, and how two systems interact.',evidence:true,apply:'Write your answer as a short geography explanation, not just a list.',more:'Earth systems often overlap in one place. A volcanic island begins with internal forces, then rain, streams, waves, plants, and soil processes change it over time. A strong geography explanation names both the process and the part of Earth it affects.'},
{t:'Geography mastery check',k:'hydrosphere, lithosphere, atmosphere, biosphere, plate tectonics, weathering, erosion, water cycle, aquifer',v:'mastery',learn:'Use this check to show enough understanding. A strong answer uses the right process word and gives evidence from the situation.',questions:['Classify clouds as atmosphere, hydrosphere, lithosphere, or biosphere and explain why.','Name Earth’s three internal layers from outside to inside.','What does plate tectonics explain?','What is the difference between subduction and spreading?','A rock cracks when water freezes inside it. Weathering or erosion?','A river carries sediment downstream. Weathering or erosion?','Put evaporation, condensation, and precipitation in order.','Why is usable freshwater limited?','What is an aquifer and why does it matter?'],apply:'Write the chapter idea in your own words: Earth changes because...',more:'A successful answer should include Earth spheres, plate movement, surface processes, and water movement.'}
]}}};
