function guideVisual(st){let items=st.see||[];let cls=st.v||'cards';if(st.v==='pyramid')return `<div class="visual-box pyramid">${items.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;if(st.v==='earth')return `<div class="visual-box earth-model">${items.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;if(st.v==='cycle')return `<div class="visual-box cycle">${items.map(x=>`<span>${esc(x)}</span>`).join('<b>-></b>')}</div>`;if(st.v==='web')return `<div class="visual-box web">${items.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;return `<div class="visual-box ${esc(cls)}">${items.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}
function normalizeStepActivity(st,idx){let base={subject:S.subject,chapter:S.chapter,id:`${S.subject}-${S.chapter}-guide-${idx}`,conceptId:st.k||'',prompt:st.try||st.t||'Learning activity'};if(st.sort)return {...base,type:'sort',...st.sort,id:st.sort.id||base.id};if(st.sequence)return {...base,type:'sequence',...st.sequence,id:st.sequence.id||base.id};if(st.choices)return {...base,type:'choice',options:st.choices.map((c,i)=>({id:`choice-${i}`,label:String(c[0]||''),explanation:String(c[2]||''),correct:!!c[1]})),correctAnswer:`choice-${Math.max(0,st.choices.findIndex(c=>!!c[1]))}`};if(st.questions)return {...base,type:'shortResponseGroup',questions:st.questions};if(st.try)return {...base,type:'shortResponse',saveAutomatically:true};return null}
function activityKey(a,field){return `${a.subject}-${a.chapter}-activity-${a.id}-${field}`}
function activityState(a){let s=saved[activityKey(a,'state')]||{};if(a.type==='sort'&&!s.placements)s.placements=saved[`${a.subject}-${a.chapter}-sort-${a.id}-placements`]||{};return s&&typeof s==='object'?s:{}}
function saveActivityProgress(a,state,completed=false,score=0){saved[activityKey(a,'state')]={...activityState(a),...state,completed,score,updatedAt:new Date().toISOString()};if(completed)saved[activityKey(a,'completed')]=true;saved[`${a.subject}-${a.chapter}-progress`]=Math.max(saved[`${a.subject}-${a.chapter}-progress`]||0,.2);save()}
function validateActivity(a){let errors=[];if(!a)errors.push('missing activity');else{if(!a.id)errors.push('missing id');if(!a.subject)errors.push('missing subject');if(!a.chapter)errors.push('missing chapter');if(!a.type)errors.push('missing type');if(!String(a.prompt||'').trim())errors.push('missing prompt');if(a.type==='choice'){let ids=(a.options||[]).map(o=>o.id);if((a.options||[]).length<2)errors.push('choice needs at least 2 options');if(new Set(ids).size!==ids.length)errors.push('duplicate option IDs');if(!ids.includes(a.correctAnswer))errors.push('correctAnswer is not an option');if((a.options||[]).some(o=>!String(o.label||'').trim()))errors.push('option label missing')}if(a.type==='sort'){let gids=(a.groups||[]).map(g=>g.id),iids=(a.items||[]).map(i=>i.id);if((a.groups||[]).length<2)errors.push('sort needs at least 2 groups');if(!(a.items||[]).length)errors.push('sort needs items');if(new Set(gids).size!==gids.length||new Set(iids).size!==iids.length)errors.push('duplicate IDs');if((a.items||[]).some(i=>!gids.includes(i.correctGroupId)))errors.push('item points to missing group');if((a.items||[]).some(i=>!String(i.label||'').trim()))errors.push('item label missing')}if(a.type==='sequence'){let orders=(a.items||[]).map(i=>i.order);if(!(a.items||[]).length)errors.push('sequence needs items');if((a.items||[]).some(i=>!Number.isFinite(Number(i.order))))errors.push('sequence order missing');if(new Set(orders).size!==orders.length)errors.push('duplicate sequence order');if((a.items||[]).some(i=>!String(i.label||'').trim()))errors.push('sequence label missing')}}return errors}
function activityRequiresCompletion(a){return a&&['choice','sort','sequence'].includes(a.type)}
function activityComplete(a){let s=activityState(a);if(a.type==='choice')return s.selected===a.correctAnswer;if(a.type==='sort')return (a.items||[]).every(i=>(s.placements||{})[i.id]===i.correctGroupId);if(a.type==='sequence')return (s.sequence||[]).length===a.items.length&&(s.sequence||[]).every((id,i)=>id===a.items.slice().sort((x,y)=>x.order-y.order)[i].id);return false}
function isStepReady(st,idx){let a=normalizeStepActivity(st,idx);return !activityRequiresCompletion(a)||activityComplete(a)}
function renderActivity(a){try{let errors=validateActivity(a);if(errors.length)return `<div class="activity-error"><strong>Activity configuration issue</strong><p>${esc(errors.join('; '))}</p></div>`;if(a.type==='choice')return renderChoiceActivity(a);if(a.type==='sort')return renderSortActivity(a);if(a.type==='sequence')return renderSequenceActivity(a);if(a.type==='shortResponseGroup')return `<div class="check-grid">${a.questions.map((q,i)=>`<label><strong>${i+1}. ${esc(q)}</strong><textarea data-autosave-key="${esc(guideSaveKey(Number(a.id.split('-').pop())||0,'q'+i))}" placeholder="Short answer">${esc(saved[guideSaveKey(Number(a.id.split('-').pop())||0,'q'+i)]||'')}</textarea></label>`).join('')}</div>`;return `<p>${esc(a.prompt)}</p>`}catch(e){return `<div class="activity-error"><strong>This activity couldn't load.</strong><p>You can continue to the next lesson block.</p><small class="muted">${esc(a?.id||'unknown activity')}</small></div>`}}
function renderChoiceActivity(a){let s=activityState(a),complete=activityComplete(a);return `<div class="activity" data-activity-id="${esc(a.id)}"><p><strong>Directions:</strong> Read the situation, then choose one answer.</p><p>${esc(a.prompt)}</p><div class="choice-row">${a.options.map(o=>`<button class="secondary activity-choice ${s.selected===o.id?'picked':''} ${complete&&o.id===a.correctAnswer?'correct':''}" data-activity-action="choice" data-activity-id="${esc(a.id)}" data-option-id="${esc(o.id)}">${esc(o.label)}${complete&&o.id===a.correctAnswer?' ✓':''}</button>`).join('')}</div><div class="${complete?'sort-success':'sort-feedback'}">${complete?esc(a.options.find(o=>o.id===a.correctAnswer)?.explanation||'Correct.'):esc(s.feedback||'Choose the best answer.')}</div></div>`}
function renderSortActivity(a){let s=activityState(a),p=s.placements||{},selected=s.selected||'',complete=activityComplete(a),unsorted=a.items.filter(i=>!p[i.id]);return `<div class="sorting activity" data-activity-id="${esc(a.id)}"><p><strong>Directions:</strong> Drag or click each card into the correct group.</p><p>${esc(a.prompt)}</p><div class="sort-unsorted">${unsorted.length?unsorted.map(i=>sortCardData(a,i,selected,false)).join(''):'<p class="muted">All cards have been placed.</p>'}</div><div class="sort-zones">${a.groups.map(g=>`<section class="sort-zone ${complete?'complete':''}" data-activity-action="sort-place" data-activity-id="${esc(a.id)}" data-group-id="${esc(g.id)}"><button class="sort-zone-head" data-activity-action="sort-place" data-activity-id="${esc(a.id)}" data-group-id="${esc(g.id)}"><strong>${esc(g.label)}</strong><small>${esc(g.description||'')}</small></button><div class="sort-zone-cards">${a.items.filter(i=>p[i.id]===g.id).map(i=>sortCardData(a,i,selected,true)).join('')}</div></section>`).join('')}</div><div class="sort-actions"><button class="secondary" data-activity-action="reset" data-activity-id="${esc(a.id)}">Reset activity</button><span class="${complete?'sort-success':'sort-feedback'}">${complete?'✓ Nice work — all '+a.items.length+' are sorted correctly.':esc(s.feedback||'Click a card, then click a group. You can also drag a card into a group.')}</span></div></div>`}
function sortCardData(a,item,selected,locked){return `<button class="sort-card ${locked?'correct':''} ${selected===item.id?'selected':''}" draggable="${locked?'false':'true'}" data-activity-action="sort-select" data-activity-id="${esc(a.id)}" data-item-id="${esc(item.id)}">${esc(item.label)}${locked?' <span aria-hidden="true">✓</span>':''}</button>`}
function renderSequenceActivity(a){let s=activityState(a),seq=s.sequence||[],complete=activityComplete(a),remaining=a.items.filter(i=>!seq.includes(i.id));return `<div class="sequence activity" data-activity-id="${esc(a.id)}"><p><strong>Directions:</strong> Put the cards in the correct order.</p><p>${esc(a.prompt)}</p><div class="sequence-row">${seq.map((id,i)=>{let item=a.items.find(x=>x.id===id);return `<span class="sequence-chip correct">${i+1}. ${esc(item?.label||id)} ✓</span>`}).join('')}</div><div class="sort-unsorted">${remaining.map(i=>`<button class="sort-card" data-activity-action="sequence-pick" data-activity-id="${esc(a.id)}" data-item-id="${esc(i.id)}">${esc(i.label)}</button>`).join('')}</div><div class="sort-actions"><button class="secondary" data-activity-action="reset" data-activity-id="${esc(a.id)}">Reset activity</button><span class="${complete?'sort-success':'sort-feedback'}">${complete?'✓ Nice work — the full sequence is correct.':esc(s.feedback||'Click the cards in the correct order.')}</span></div></div>`}
function guideTry(ch,st,idx){return renderActivity(normalizeStepActivity(st,idx))}
function guideText(ch,idx,field,prompt){return `<label class="activity-response"><span>${injectTerms(prompt,ch)}</span><textarea data-autosave-key="${esc(guideSaveKey(idx,field))}" oninput='saveGuideText(${idx},${JSON.stringify(field)},this.value)' placeholder="Write here. This saves automatically.">${esc(saved[guideSaveKey(idx,field)]||'')}</textarea><small>Saved automatically.</small></label>`}
function guideSaveKey(idx,field){return `${S.subject}-${S.chapter}-guide-${idx}-${field}`}
function saveGuideText(idx,field,value){saved[guideSaveKey(idx,field)]=value;saved[S.subject+'-'+S.chapter+'-progress']=Math.max(saved[S.subject+'-'+S.chapter+'-progress']||0,.25);save()}
function setGuideStep(i){let guide=guideFor(chap());let key=`${S.subject}-${S.chapter}-guide-step`;saved[key]=Math.max(0,Math.min(guide.steps.length-1,i));save();navigate();window.scrollTo(0,0)}
function currentActivityById(id){let guide=guideFor(chap());if(!guide)return null;for(let i=0;i<guide.steps.length;i++){let a=normalizeStepActivity(guide.steps[i],i);if(a&&a.id===id)return a}return null}
function completeGuideStep(){let guide=guideFor(chap());let key=`${S.subject}-${S.chapter}-guide-step`;let idx=Math.max(0,Math.min(guide.steps.length-1,Number(saved[key]||0)));let st=guide.steps[idx],a=normalizeStepActivity(st,idx);if(!isStepReady(st,idx)){if(a)saveActivityProgress(a,{...activityState(a),feedback:'Finish the activity correctly before continuing.'},false,0);render(false);return}saved[`${S.subject}-${S.chapter}-guide-done-${idx}`]=true;if(st.evidence||st.questions||a)saved[`${S.subject}-${S.chapter}-evidence-${idx}`]=new Date().toISOString();saved[S.subject+'-'+S.chapter+'-progress']=Math.max(saved[S.subject+'-'+S.chapter+'-progress']||0,(idx+1)/guide.steps.length);if(idx<guide.steps.length-1)saved[key]=idx+1;save();navigate();window.scrollTo(0,0)}
function handleActivityClick(target){let el=target.closest('[data-activity-action]');if(!el)return false;let action=el.dataset.activityAction,id=el.dataset.activityId,a=currentActivityById(id);if(!a)return true;let s=activityState(a);if(action==='reset'){saveActivityProgress(a,{feedback:'Activity reset. Try again.'},false,0);render(false);return true}if(action==='choice'){let selected=el.dataset.optionId,ok=selected===a.correctAnswer,opt=a.options.find(o=>o.id===selected);saveActivityProgress(a,{selected,feedback:ok?(opt?.explanation||'Correct.'):'Try again.'},ok,ok?1:0);render(false);return true}if(action==='sort-select'){saveActivityProgress(a,{...s,selected:el.dataset.itemId,feedback:'Choose a group.'},activityComplete(a),0);render(false);return true}if(action==='sort-place'){let itemId=s.selected;if(!itemId)return true;let item=a.items.find(i=>i.id===itemId),groupId=el.dataset.groupId,p={...(s.placements||{})};if(item&&item.correctGroupId===groupId){p[itemId]=groupId;let next={...s,placements:p,selected:'',feedback:'Nice. '+item.label+' is placed.'};saveActivityProgress(a,next,a.items.every(i=>p[i.id]===i.correctGroupId),Object.keys(p).length)}else saveActivityProgress(a,{...s,selected:'',feedback:'Try again.'},false,0);render(false);return true}if(action==='sequence-pick'){let itemId=el.dataset.itemId,ordered=a.items.slice().sort((x,y)=>x.order-y.order),seq=[...(s.sequence||[])],expected=ordered[seq.length];if(expected&&expected.id===itemId){seq.push(itemId);saveActivityProgress(a,{...s,sequence:seq,feedback:'Nice. Keep going.'},seq.length===ordered.length,seq.length)}else saveActivityProgress(a,{...s,feedback:'Try again.'},false,seq.length);render(false);return true}return true}
function handleActivityDragStart(e){let el=e.target.closest('[data-activity-action="sort-select"]');if(!el)return;e.dataTransfer.setData('text/plain',JSON.stringify({activityId:el.dataset.activityId,itemId:el.dataset.itemId}))}
function handleActivityDrop(e){let el=e.target.closest('[data-activity-action="sort-place"]');if(!el)return;e.preventDefault();try{let data=JSON.parse(e.dataTransfer.getData('text/plain')||'{}'),a=currentActivityById(data.activityId);if(!a)return;saveActivityProgress(a,{...activityState(a),selected:data.itemId},false,0);handleActivityClick(el)}catch(_){}}
function alignedActivity(meta,ch){let t=meta.vocabulary[0]||termInfo({term:meta.title}),section=meta.title,base={activityId:`${meta.subject}-ch${meta.chapter}-s${meta.sectionIndex+1}-${meta.conceptId}`,subject:meta.subject,chapter:meta.chapter,section:meta.section,learningObjectiveId:meta.learningObjectiveId,conceptId:meta.conceptId,interactionType:meta.interactionType,sourceBasis:meta.sourceBasis};
if(meta.subject==='math'){let act=(ch.sections?.[meta.sectionIndex]?.math?.activity)||{},kind=meta.interactionType||act.type||'math-solve',question=act.prompt||`Use ${section} to solve, graph, model, or justify a math idea.`,answer=act.answer||'Show the setup, the mathematical steps, and what the result means.';let visuals=kind==='graph'?['Table','Point','Slope/shape','Equation']:kind==='data-analysis'?['Data values','Display','Center/spread','Conclusion']:kind==='reasoning'?['Given','Claim','Reason','Conclusion']:['Given','Operation','Solution','Check'];return {...base,title:kind==='graph'?'Try It: Graph and Explain':kind==='data-analysis'?'Try It: Interpret Data':kind==='reasoning'?'Try It: Build the Argument':'Try It: Solve and Check',scenario:`${section} asks Liam to connect the procedure to the reason it works.`,question,choices:['Set up the representation, complete the math, and explain the result.','Guess the answer and skip the representation.','Copy a formula without saying what the numbers mean.'],answer,steps:visuals,apply:`Show your work for ${section}. Then write one sentence explaining why the step, graph, table, or argument makes sense.`}}
if(meta.conceptId==='biology-characteristics-of-life')return {...base,title:'Try It: Classify Life Evidence',scenario:'A student observes four things: a sprouting bean seed, a candle flame, a toy robot, and a pond bacterium.',question:'Which observations would help a biologist decide whether something is living?',choices:['Growth, using energy, response to surroundings, cells, and reproduction.','Only whether it moves across a table.','Only whether it is warm or gives off light.'],answer:'A strong answer uses characteristics of living things, not just one surface clue.',steps:['Observe examples','Look for life characteristics','Choose evidence','Explain classification'],apply:'Choose one example and explain which evidence makes it living or nonliving.'}
if(meta.conceptId==='scientific-investigation')return {...base,title:'Try It: Design the Investigation',scenario:'Moss seems to grow more often in shady, damp places than in sunny, dry places.',question:'Which plan best tests a scientific hypothesis about moss growth?',choices:['Change one condition, such as light, measure moss growth, and keep water and soil similar.','Move moss randomly and decide by opinion.','Measure only the prettiest moss and ignore conditions.'],answer:'A strong answer names the observation, a testable hypothesis, one changed variable, one measured variable, and what stays the same.',steps:['Observation','Hypothesis','Variable changed','Data measured'],apply:'Write a testable hypothesis for the moss question and name what you would measure.'}
if(meta.conceptId==='quantitative-vs-qualitative-data')return {...base,title:'Try It: Sort the Observations',scenario:'A student records: “The leaf is 8 cm long. The flower is bright yellow. The plant has 12 leaves. The stem feels rough. The water temperature is 22°C.”',question:'Which choice correctly separates quantitative and qualitative observations?',choices:['Quantitative: 8 cm, 12 leaves, 22°C. Qualitative: bright yellow, rough stem.','Quantitative: bright yellow and rough stem. Qualitative: 8 cm and 22°C.','All observations are quantitative because they are about plants.'],answer:'Quantitative observations use numbers or measurements. Qualitative observations describe qualities.',steps:['Read observation','Find numbers','Find descriptions','Sort data type'],apply:'In “The plant grew 4 cm and its leaves became pale,” identify the quantitative part and the qualitative part.'}
if(meta.conceptId==='ecosystem-parts')return {...base,title:'Try It: Sort Ecosystem Evidence',scenario:`In ${section}, Liam studies a pond with fish, algae, water, rocks, sunlight, and dissolved oxygen.`,question:'Which evidence separates living parts from nonliving conditions?',choices:['Fish and algae are living; water, rocks, sunlight, and dissolved oxygen are nonliving conditions.','Everything in the pond is living because it is outdoors.','Only rocks matter because they are easiest to see.'],answer:'Use biotic for living or once-living parts and abiotic for nonliving conditions.',steps:['Pond example','Living parts','Nonliving conditions','Effect on system'],apply:'Name one biotic and one abiotic factor from the lesson, then explain how one can affect the other.'}
if(meta.conceptId==='energy-flow-matter-cycle')return {...base,title:'Try It: Trace Energy and Matter',scenario:`A section about ${section} shows organisms connected by feeding relationships.`,question:'Which explanation follows the chapter idea?',choices:['Energy moves through feeding relationships while matter is reused in cycles.','Energy and matter disappear after one organism eats another.','Only the largest animal has energy.'],answer:'Use producers, consumers, decomposers, energy flow, or matter cycling as the section requires.',steps:['Producer/input','Consumer link','Matter reused','Energy flow'],apply:'Use one food-chain or matter-cycle example from this section and explain what moves where.'}
if(meta.conceptId==='cell-structure-function')return {...base,title:'Try It: Match Structure to Job',scenario:`A cell diagram in ${section} shows several parts that each do a job.`,question:'Which answer best uses structure-function thinking?',choices:[`${t.term} matters because its structure helps it do a specific job in the cell.`,`Cell parts do not have jobs.`,`Every cell part does the exact same thing.`],answer:`Explain ${t.term} by connecting the structure to what it does.`,steps:['Cell part','Structure clue','Function','Why it matters'],apply:`Describe the job of ${t.term} and how it helps the cell.`}
if(meta.conceptId==='cell-transport')return {...base,title:'Try It: Predict Movement Across a Membrane',scenario:`A membrane separates two areas with different concentrations during ${section}.`,question:'What should you consider before predicting movement?',choices:['The concentration difference and whether the transport uses energy.','Only the color of the picture.','Whether the word is long or short.'],answer:'Use concentration, membrane, diffusion, osmosis, passive transport, or active transport as taught in the section.',steps:['Membrane','Concentration difference','Movement','Energy?'],apply:'Predict the direction of movement in one membrane example and explain why.'}
if(meta.conceptId==='cell-energy-process')return {...base,title:'Try It: Sequence the Energy Process',scenario:`The section ${section} explains a process that changes matter and energy in cells.`,question:'Which reasoning matches the lesson?',choices:['Name the inputs, follow the process, and identify the outputs.','Skip the inputs and guess the output.','Assume all cell energy processes are identical.'],answer:'Use the process order and the correct inputs and outputs from the section.',steps:['Inputs','Process steps','Outputs','Cell use'],apply:'Name one input and one output from this section’s energy process.'}
if(meta.conceptId==='cell-division-sequence')return {...base,title:'Try It: Put the Cell Event in Order',scenario:`A cell must complete the events described in ${section} in a workable order.`,question:'What kind of evidence helps you sequence it?',choices:['Chromosome position, copying, separation, and the result for new cells.','The color of the textbook heading.','Only the final picture, with no steps.'],answer:'Use the sequence of cell-cycle, mitosis, or meiosis events from the section.',steps:['Start state','Copy/line up','Separate','Result'],apply:'Write two events from the section in the correct order and explain why that order matters.'}
if(meta.conceptId==='genetic-information')return {...base,title:'Try It: Use Genetic Instructions',scenario:`In ${section}, genetic information affects a trait or cell process.`,question:'Which answer uses genetic reasoning?',choices:['DNA or genes provide instructions that can affect proteins, traits, or inheritance.','Genes are random decorations inside cells.','Traits never connect to inherited information.'],answer:'Use DNA, gene, chromosome, protein, mutation, or heredity accurately.',steps:['Genetic information','Instruction/change','Trait or protein','Evidence'],apply:`Explain how ${t.term} connects to a trait, protein, or inherited pattern.`}
if(meta.conceptId==='evolution-evidence')return {...base,title:'Try It: Compare Evolution Evidence',scenario:`A population in ${section} shows variation and some traits help survival or reproduction.`,question:'Which explanation uses evidence correctly?',choices:['Traits that improve survival or reproduction can become more common over generations.','An individual chooses to evolve instantly.','All variation disappears before selection can happen.'],answer:'Use adaptation, variation, natural selection, fossil evidence, or classification evidence from the section.',steps:['Variation','Environment','Survival/reproduction','Change over time'],apply:'Use one piece of evidence from the section to explain an evolutionary change.'}
if(meta.conceptId==='location-coordinates')return {...base,title:'Try It: Read the Location',scenario:`A map in ${section} gives a place using latitude and longitude coordinates.`,question:'What kind of location uses coordinates?',choices:['Absolute location, because coordinates identify an exact position.','Relative location, because it only compares nearby landmarks.','A region, because coordinates always describe culture.'],answer:'Latitude and longitude give absolute location.',steps:['Latitude','Longitude','Exact point','Explain'],apply:'Give one absolute-location clue and one relative-location clue for the same place.'}
if(meta.conceptId==='region-classification')return {...base,title:'Try It: Classify the Region',scenario:`The section ${section} describes a place that can be grouped by shared features, connections, or people’s perceptions.`,question:'Which evidence helps identify the type of region?',choices:['Shared features, linked activities, or how people describe the place.','Only whether the place name is short.','Only whether it appears first on the page.'],answer:'Use formal, functional, or perceptual region evidence as appropriate.',steps:['Place evidence','Shared or linked?','Region type','Explain'],apply:'Name the region type shown in one section example and explain the evidence.'}
if(meta.conceptId==='earth-spheres')return {...base,title:'Try It: Sort Earth Spheres',scenario:`In ${section}, examples include water, land or rock, air, and living things.`,question:'Which sorting matches Earth’s spheres?',choices:['Hydrosphere water; lithosphere land and rock; atmosphere air; biosphere life.','All examples belong only to the atmosphere.','Living things are part of the lithosphere because they stand on land.'],answer:'Use the four Earth spheres and explain how they interact.',steps:['Water','Land/rock','Air','Life'],apply:'Choose two Earth spheres from the section and explain how they interact.'}
if(meta.conceptId==='plate-tectonics')return {...base,title:'Try It: Explain the Earth Force',scenario:`A map or diagram in ${section} shows plates moving and shaping Earth’s surface.`,question:'Which explanation fits plate tectonics?',choices:['Plate movement can build mountains, cause earthquakes, create volcanoes, or reshape ocean basins.','Plates never move.','Only weather changes Earth’s interior.'],answer:'Use plate motion and its surface effect.',steps:['Plate movement','Boundary/action','Landform/event','Evidence'],apply:'Use one plate movement example from the section and explain its result.'}
if(meta.conceptId==='weathering-vs-erosion')return {...base,title:'Try It: Weathering or Erosion?',scenario:`The section ${section} includes rock breaking down and material being moved.`,question:'Which answer correctly separates the two processes?',choices:['Weathering breaks material down; erosion moves material away.','Weathering and erosion always mean exactly the same thing.','Erosion only happens inside Earth.'],answer:'Identify whether the example breaks material or transports it.',steps:['Rock/material','Break down?','Move away?','Classify'],apply:'Create one weathering example and one erosion example from this section’s setting.'}
if(meta.conceptId==='water-cycle')return {...base,title:'Try It: Sequence Water Movement',scenario:`A drop of water moves through the process described in ${section}.`,question:'Which order follows the water cycle?',choices:['Evaporation, condensation, precipitation, then runoff or groundwater.','Precipitation, evaporation, condensation, then the Sun disappears.','Groundwater happens before any water reaches Earth.'],answer:'Use the water-cycle steps and explain where the water goes.',steps:['Evaporation','Condensation','Precipitation','Runoff/groundwater'],apply:'Trace one drop of water through three steps from this section.'}
if(meta.conceptId==='climate-patterns')return {...base,title:'Try It: Read Climate Evidence',scenario:`A climate graph or map in ${section} shows temperature, precipitation, and vegetation patterns.`,question:'What evidence should you use first?',choices:['Temperature, precipitation, location, and vegetation clues.','Only the map color with no legend.','Only the name of the chapter.'],answer:'Use climate data and location evidence together.',steps:['Temperature','Precipitation','Vegetation','Pattern'],apply:'Use one climate clue and one vegetation or location clue to explain a place pattern.'}
if(meta.conceptId==='population-movement')return {...base,title:'Try It: Explain a Population Pattern',scenario:`A population map in ${section} shows people clustered in some places more than others.`,question:'Which evidence best explains the pattern?',choices:['Physical features, resources, jobs, transportation, or migration causes.','People always settle evenly everywhere.','Population patterns never change.'],answer:'Use map evidence and reasons for settlement or movement.',steps:['Where people are','Physical/human factor','Movement/settlement','Reason'],apply:'Explain one population or migration pattern from the section using map evidence.'}
if(meta.conceptId==='trade-resource-patterns')return {...base,title:'Try It: Follow the Resource Route',scenario:`The section ${section} connects resources, trade, transportation, or economic activity.`,question:'Which explanation uses geographic evidence?',choices:['Resources, routes, and markets can shape where trade and industry grow.','Trade happens without places, routes, or resources.','Only climate determines every economic pattern.'],answer:'Use the resource, route, and place evidence from the section.',steps:['Resource','Route','Market/place','Effect'],apply:'Name one resource or route from the section and explain why it matters.'}
if(meta.conceptId==='cultural-geography')return {...base,title:'Try It: Compare Cultural Evidence',scenario:`The section ${section} describes language, religion, history, settlement, or government patterns.`,question:'What makes this a cultural geography question?',choices:['It uses human patterns and how people organize or identify places.','It ignores people completely.','It only measures rainfall.'],answer:'Use a specific cultural feature and connect it to place.',steps:['People','Cultural feature','Place pattern','Explain'],apply:'Compare two cultural features or places from the section.'}
let geo=S.subject==='geography';
return {...base,title:geo?'Try It: Use Section Map Evidence':'Try It: Use Section Evidence',scenario:geo?`In ${section}, a place pattern is connected to ${t.term}.`:`In ${section}, an observation is connected to ${t.term}.`,question:geo?`Which evidence from ${section} would help explain the place pattern?`:`Which evidence from ${section} supports the biological idea?`,choices:[geo?`Use the specific place, pattern, and ${t.term} evidence from this section.`:`Use the specific observation, example, and ${t.term} evidence from this section.`,'Use an unrelated example from another chapter.','Guess without naming evidence.'],answer:geo?`Name the place or pattern and connect it to ${t.term}.`:`Name the observation and connect it to ${t.term}.`,steps:geo?['Place','Pattern',t.term,'Why it matters']:['Observation',t.term,'Evidence','Explanation'],apply:geo?`Apply ${t.term} to one place or pattern from ${section}.`:`Apply ${t.term} to one example from ${section}.`}}
function conceptActivity(ch,si){let s=ch.sections[si]||{},meta=sectionMeta(ch,s,si),sc=alignedActivity(meta,ch),info=meta.vocabulary[0]||termInfo({term:meta.title}),subject=S.subject,key=`${S.subject}-${ch.number}-activity-${si}`,value=saved[key]||'',picked=saved[`${key}-choice`];return `<div class="interaction" data-concept-activity="${esc(key)}" data-activity-id="${esc(sc.activityId)}" data-section="${esc(sc.section)}" data-concept-id="${esc(sc.conceptId)}" data-objective-id="${esc(sc.learningObjectiveId)}"><strong>${esc(sc.title)}</strong><p><strong>Learning target:</strong> ${esc(meta.learningObjectives[0])}</p><p><strong>Situation:</strong> ${esc(sc.scenario)}</p><p><strong>Question:</strong> ${esc(sc.question)}</p><div class="choice-row">${sc.choices.map((choice,i)=>`<button class="secondary ${picked===i?'picked':''}" data-concept-action="feedback" data-concept-key="${esc(key)}" data-ok="${i===0?'1':'0'}" data-term="${esc(info.term)}" data-definition="${esc(sc.answer)}" data-example="${esc(sc.apply)}">${esc(choice)}</button>`).join('')}</div><div class="mini-visual ${subject==='biology'?'bio-mini':'geo-mini'}">${sc.steps.map((x,i)=>`${i?'<b>→</b>':''}<span>${esc(x)}</span>`).join('')}</div><label class="activity-response"><span>Apply</span><textarea data-autosave-key="${esc(key)}" placeholder="${esc(sc.apply)}">${esc(value)}</textarea><small>Saved automatically.</small></label><div class="fb">${saved[`${key}-feedback`]||''}</div></div>`}
function saveActivity(i,v){saved[`${S.subject}-${S.chapter}-activity-${i}`]=v;saved[S.subject+'-'+S.chapter+'-progress']=Math.max(saved[S.subject+'-'+S.chapter+'-progress']||0,.2);save()}
function miniVisual(ch,info){if(S.subject==='biology')return `<span>Observe</span><b>→</b><span>${esc(info.term)}</span><b>→</b><span>Predict</span><b>→</b><span>Explain with evidence</span>`;return `<span>Where?</span><b>→</b><span>${esc(info.term)}</span><b>→</b><span>Pattern</span><b>→</b><span>Why there?</span>`}
function showConceptFeedback(btn){let key=btn.dataset.conceptKey,ok=btn.dataset.ok==='1',term=btn.dataset.term||'',def=btn.dataset.definition||'',example=btn.dataset.example||'',box=btn.closest('.interaction');btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('picked'));btn.classList.add('picked');let html=ok?`<div class="feedback"><strong>${esc(term)}</strong>: ${esc(def)}<br>${esc(example)}</div>`:`<div class="feedback warn"><strong>Try again.</strong> A good answer connects the term to evidence and a real example.</div>`;if(box)box.querySelector('.fb').innerHTML=html;if(key){saved[`${key}-choice`]=[...btn.parentElement.querySelectorAll('button')].indexOf(btn);saved[`${key}-feedback`]=html;saved[S.subject+'-'+S.chapter+'-progress']=Math.max(saved[S.subject+'-'+S.chapter+'-progress']||0,.2);save()}}
function words(ch){return `<div class="card"><h2>Important words</h2><p class="muted">Click any word to see what it means, context, and an example from the chapter.</p><div class="glossary-grid">${ch.vocabulary.map(v=>{let info=termInfo(v);return `<button class="glossary-item" onclick='termModal(${JSON.stringify(v.term)})'><strong>${esc(info.term)}</strong><div class="muted" style="margin-top:6px">${esc(info.definition.slice(0,150))}${info.definition.length>150?'…':''}</div></button>`}).join('')}</div></div>`}
function termModal(term){let v=chap().vocabulary.find(x=>x.term===term) || Object.values(S.data).flatMap(c=>c.chapters).flatMap(c=>c.vocabulary).find(x=>x.term===term) || (TERM_DEFS[S.subject]?.[String(term).toLowerCase()]?{term}:null);if(!v)return;let info=termInfo(v);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="document.getElementById('modal').remove()">✕</button><div class="eyebrow">Important word</div><h2>${esc(info.term)}</h2><h3>What it means</h3><p>${esc(info.definition)}</p><h3>Example</h3><p>${esc(info.example)}</p><h3>In the chapter</h3><p>${esc(info.context)}</p><div class="interaction"><strong>Check yourself</strong><p>Can you explain this term in your own words and give one example?</p></div></div></div>`)}
function notes(ch){let guide=guideFor(ch);if(guide)return guideNotes(ch,guide);let metas=(ch.sections||[]).map((s,i)=>sectionMeta(ch,s,i));return `<div class="grid"><div class="card"><h2>Study guide</h2><h3>Big ideas</h3>${metas.slice(0,6).map(m=>`<p>• ${injectTerms(m.learningObjectives[0],ch)}</p>`).join('')}<h3>Important words</h3>${ch.vocabulary.slice(0,12).map(x=>`<button class="term" onclick='termModal(${JSON.stringify(x.term)})'>${esc(x.term)}</button> `).join('')}<h3>Know this</h3>${ch.vocabulary.slice(0,6).map(v=>{let i=termInfo(v);return `<p>• <strong>${esc(i.term)}</strong>: ${esc(i.definition)}</p>`}).join('')}<h3>Be able to explain</h3>${metas.map(m=>`<p>• ${injectTerms(m.title,ch)}: ${esc(m.conceptId)}</p>`).join('')}<h3>Be able to apply</h3>${metas.slice(0,4).map((m,i)=>`<p>• ${injectTerms(alignedActivity(m,ch).apply,ch)}</p>`).join('')}</div><div class="card"><h2>Chapter notes</h2>${(ch.sections||[]).map((s,i)=>`<h3>${injectTerms(sectionMeta(ch,s,i).title,ch)}</h3>${sectionBlocks(ch,s,i).map(b=>`<p>${injectTerms(b,ch)}</p>`).join('')}`).join('')}</div></div>`}
function guideNotes(ch,guide){let terms=guide.steps.flatMap(s=>String(s.k||'').split(',').map(x=>x.trim()).filter(Boolean));let seen=new Set();terms=terms.filter(t=>{let k=t.toLowerCase();if(seen.has(k))return false;seen.add(k);return true});return `<div class="grid"><div class="card"><h2>Study guide</h2><h3>Big idea</h3><p>${injectTerms(guide.big,ch)}</p><h3>Important words</h3>${terms.map(t=>`<button class="term" onclick='termModal(${JSON.stringify(t)})'>${esc(t)}</button> `).join('')}<h3>Know this</h3>${guide.mastery.map(x=>`<p>• ${injectTerms(x,ch)}</p>`).join('')}<h3>Understand this</h3>${guide.steps.slice(0,-1).map(s=>`<p>• ${injectTerms(s.learn.split('.')[0]+'.',ch)}</p>`).join('')}<h3>Be able to apply</h3><p>${S.subject==='biology'?'Classify ecosystem parts, interpret feeding relationships, and explain how a change in one factor affects others.':'Use Earth-system evidence to explain spheres, landform changes, plate processes, weathering, erosion, and water movement.'}</p></div><div class="card"><h2>Chapter notes</h2>${guide.steps.slice(0,-1).map((s,i)=>`<h3>${injectTerms(s.t,ch)}</h3><p>${injectTerms(s.learn,ch)}</p><p class="muted">${injectTerms(tellMoreContent(ch,guideStepMeta(ch,s,i),s.more||''),ch)}</p>`).join('')}</div></div>`}
function worksheet(ch){let key=`${S.subject}-${ch.number}-worksheet`;let vals=saved[key]||{};return `<div class="card"><div class="actions no-print"><button class="primary" onclick="exportWorksheet('blank')">Export blank PDF</button><button class="primary" onclick="exportWorksheet('completed')">Export completed PDF</button><button class="secondary" onclick="window.print()">Print / Save PDF</button><button class="secondary" onclick="exportWorksheet('key')">Parent answer key PDF</button></div><h1>${esc(course().name)} Chapter ${ch.number} Worksheet</h1><p>Student: Liam DeVries &nbsp;&nbsp; Grade: 9 &nbsp;&nbsp; Date: ${new Date().toLocaleDateString()}</p>${worksheetItems(ch).map((q,i)=>`<div class="worksheet-item ${esc(q.type)}"><div class="eyebrow">${esc(questionLabel(q.type))}</div><strong>${i+1}. ${injectTerms(q.prompt,ch)}</strong>${worksheetControl(q,i,vals[i]||'')}</div>`).join('')}</div>`}
function clearPromptText(q){return usableStudentText(q)?cleanStudentText(q):''}
function termQuestion(v){let i=termInfo(v);return {type:'definition',conceptId:`term-${slugText(i.term)}`,objectiveId:`term-${slugText(i.term)}`,prompt:`In your own words, what does ${i.term} mean? Give one example.`,answer:`${i.definition} Example: ${i.example}`}}
function sectionQuestion(ch,s,si){let meta=sectionMeta(ch,s,si),activity=alignedActivity(meta,ch),type=S.subject==='math'?meta.interactionType:(meta.interactionType==='classification'?'classification':S.subject==='biology'?'scenario':'map-analysis');return {type,conceptId:meta.conceptId,objectiveId:meta.learningObjectiveId,prompt:`${activity.question} Use ${meta.title} in your answer.`,answer:activity.answer,guidance:activity.apply}}
function sectionApplyQuestion(ch,s,si){let meta=sectionMeta(ch,s,si),activity=alignedActivity(meta,ch);return {type:S.subject==='math'?(meta.interactionType||'math-solve'):S.subject==='biology'?'explain':'map-analysis',conceptId:meta.conceptId,objectiveId:meta.learningObjectiveId,prompt:activity.apply,answer:activity.answer,guidance:'Use the same idea from the lesson block.'}}
function chapterScenarioQuestion(ch){let metas=(ch.sections||[]).map((s,i)=>sectionMeta(ch,s,i));let meta=metas[0]||sectionMeta(ch,{title:ch.title,blocks:[]},0),activity=alignedActivity(meta,ch);return {type:S.subject==='math'?'math-solve':S.subject==='biology'?'scenario':'map-analysis',conceptId:meta.conceptId,objectiveId:meta.learningObjectiveId,prompt:`Chapter challenge: ${activity.scenario} ${activity.apply}`,answer:activity.answer,guidance:'Use one specific chapter concept and evidence.'}}
function worksheetItems(ch){let guide=guideFor(ch);if(guide)return guideWorksheet(ch,guide);let metas=(ch.sections||[]).map((s,i)=>({s,i,meta:sectionMeta(ch,s,i)}));let aligned=metas.flatMap(({s,i})=>[sectionQuestion(ch,s,i),sectionApplyQuestion(ch,s,i)]);let terms=(ch.vocabulary||[]).slice(0,3).map(termQuestion);let cleanBase=(ch.worksheet||[]).filter(q=>clearPromptText(q.prompt)).slice(0,2).map(q=>({...q,conceptId:'source-review',objectiveId:`${S.subject}-ch${ch.number}-source-review`,prompt:clearPromptText(q.prompt),answer:clearPromptText(q.answer)||'Use the chapter lesson and vocabulary accurately.'}));let varied=[...aligned,chapterScenarioQuestion(ch),...terms,...cleanBase];let seen=new Set();return varied.filter(q=>{let key=slugText(q.prompt);if(seen.has(key))return false;seen.add(key);return true}).slice(0,12)}
function guideWorksheet(ch,guide){if(S.subject==='biology')return [
{type:'classification',prompt:'Sort pond parts into biotic and abiotic: fish, algae, insects, water, rocks, sunlight, dissolved oxygen.',answer:'Biotic: fish, algae, insects. Abiotic: water, rocks, sunlight, dissolved oxygen.'},
{type:'sequence',prompt:'Put the organization levels in order from smallest to largest: ecosystem, population, organism, community.',answer:'organism -> population -> community -> ecosystem.'},
{type:'matching',prompt:'Match habitat and niche to these owl statements: lives in grasslands and barns; hunts mice at night.',answer:'Habitat: lives in grasslands and barns. Niche: hunts mice at night.'},
{type:'classification',prompt:'Classify each symbiosis example: ants/acacia, orchid/tree, tick/deer.',answer:'Ants/acacia: mutualism. Orchid/tree: commensalism. Tick/deer: parasitism.'},
{type:'matching',prompt:'Classify grass, rabbit, hawk, bear, vulture, and fungus by energy role.',answer:'Grass producer; rabbit herbivore; hawk carnivore; bear omnivore; vulture scavenger; fungus decomposer.'},
{type:'diagram',prompt:'In Sun -> grass -> grasshopper -> frog -> snake -> hawk, identify the producer, first consumer, and what grasshopper -> frog means.',answer:'Producer: grass. First consumer: grasshopper. Arrow means energy and matter move from grasshopper to frog.'},
{type:'scenario',prompt:'If rabbits decrease sharply in grass -> rabbit -> fox, predict what may happen to foxes and explain why.',answer:'Foxes may decrease or need other food because rabbits are an energy/matter source.'},
{type:'explain',prompt:'Explain why energy flows through ecosystems but matter cycles.',answer:'Energy moves through feeding relationships and is lost as heat; matter such as water and nutrients is recycled.'},
{type:'scenario',prompt:'Garden evidence: name 3 biotic factors, 3 abiotic factors, 1 producer, 2 consumers, 1 decomposer, and one food chain.',answer:'Accept accurate garden examples such as tomato plants, bees, caterpillars; soil, water, sunlight; tomato producer; caterpillar/bird consumers; fungus decomposer; tomato -> caterpillar -> bird.'}
];return [
{type:'classification',prompt:'Classify Pacific Ocean, mountain, cloud-bearing air, and forest life by Earth sphere.',answer:'Hydrosphere, lithosphere, atmosphere, biosphere.'},
{type:'diagram',prompt:'Label Earth layers from outside to inside.',answer:'Crust -> mantle -> core.'},
{type:'explain',prompt:'What does plate tectonics explain about Earth’s surface?',answer:'Moving plates shape continents, ocean basins, mountains, earthquakes, and volcanoes.'},
{type:'matching',prompt:'Match subduction, accretion, and spreading with: one plate sinks; material is added; plates move apart.',answer:'Subduction: one plate sinks. Accretion: material is added. Spreading: plates move apart.'},
{type:'classification',prompt:'Classify fold, fault, earthquake, and volcano as bend, break with movement, sudden shaking, or magma reaching surface.',answer:'Fold bend; fault break with movement; earthquake sudden shaking; volcano magma reaches surface.'},
{type:'classification',prompt:'A freeze crack in rock and a river carrying sediment: which is weathering and which is erosion?',answer:'Freeze crack is weathering. River carrying sediment is erosion.'},
{type:'sequence',prompt:'Put evaporation, condensation, and precipitation in order and describe each.',answer:'Evaporation liquid to vapor; condensation vapor to droplets/clouds; precipitation water falls.'},
{type:'map-analysis',prompt:'Explain why freshwater is limited even though much of Earth is covered by water.',answer:'Most water is salt water or unavailable; usable freshwater is limited and unevenly distributed.'},
{type:'scenario',prompt:'Volcanic island challenge: identify one internal force, one external force, one hydrosphere example, one lithosphere example, one biosphere example, and one system interaction.',answer:'Volcanism/internal; rain/streams erosion external; rain/streams hydrosphere; mountains lithosphere; plants biosphere; water interacts with rock and plants.'}
]}
function questionLabel(type){return ({definition:'Vocabulary in context',matching:'Match / connect',classification:'Classify',sequence:'Sequence',diagram:'Diagram / model',scenario:'Scenario',source_question:'Text evidence',explain:'Explain',check:'Mastery check','map-analysis':'Map / spatial analysis','math-solve':'Solve / check',graph:'Graph / visualize','data-analysis':'Data analysis',reasoning:'Reasoning / proof',model:'Model'}[type]||'Chapter question')}
function worksheetControl(q,i,value){if(q.type==='matching')return `<div class="match-box"><span>Term</span><b>→</b><span>Example / meaning</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Write the match or connection.">${esc(value)}</textarea>`;if(q.type==='graph')return `<div class="mini-visual math-mini"><span>Table</span><b>→</b><span>Coordinate plane</span><b>→</b><span>Feature</span><b>→</b><span>Meaning</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Describe or sketch the graph, then explain what it shows.">${esc(value)}</textarea>`;if(q.type==='math-solve')return `<div class="mini-visual math-mini"><span>Given</span><b>→</b><span>Operation</span><b>→</b><span>Solution</span><b>→</b><span>Check</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Show steps, answer, and a check.">${esc(value)}</textarea>`;if(q.type==='data-analysis')return `<div class="mini-visual math-mini"><span>Data</span><b>→</b><span>Display</span><b>→</b><span>Pattern</span><b>→</b><span>Conclusion</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Name the pattern and explain what it supports.">${esc(value)}</textarea>`;if(q.type==='reasoning')return `<div class="mini-visual math-mini"><span>Given</span><b>→</b><span>Claim</span><b>→</b><span>Reason</span><b>→</b><span>Conclusion</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Write the argument and the reason for each step.">${esc(value)}</textarea>`;if(q.type==='map-analysis')return `<div class="mini-visual geo-mini"><span>Location</span><b>→</b><span>Pattern</span><b>→</b><span>Cause</span><b>→</b><span>Decision</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Use place, pattern, and evidence.">${esc(value)}</textarea>`;if(q.type==='scenario')return `<div class="mini-visual bio-mini"><span>Evidence</span><b>→</b><span>Process</span><b>→</b><span>Prediction</span><b>→</b><span>Reason</span></div><textarea oninput="saveAnswer(${i},this.value)" placeholder="Use evidence and explain why.">${esc(value)}</textarea>`;return `<textarea oninput="saveAnswer(${i},this.value)" placeholder="Short answer is enough.">${esc(value)}</textarea>`}
function saveAnswer(i,v){let key=`${S.subject}-${S.chapter}-worksheet`;saved[key]=saved[key]||{};saved[key][i]=v;save()}
function check(ch){let key=`${S.subject}-${ch.number}-check`;let vals=saved[key]||{};let questions=knowledgeItems(ch);return `<div class="card"><h2>Knowledge check</h2><p class="muted">Each question tells you exactly what to answer. Short answers are enough.</p>${questions.map((q,i)=>`<div class="worksheet-item"><div class="eyebrow">${esc(questionLabel(q.type||'check'))}</div><strong>${i+1}. ${injectTerms(q.prompt,ch)}</strong><textarea oninput="saveCheck(${i},this.value)" placeholder="${esc(q.guidance||'Answer in 1-3 sentences.')}">${esc(vals[i]||'')}</textarea><button class="secondary no-print" onclick="revealAnswer(this,${JSON.stringify(q.answer)})">Check answer</button><div class="fb"></div></div>`).join('')}</div>`}
function knowledgeItems(ch){let guide=guideFor(ch);if(guide){let last=guide.steps[guide.steps.length-1];return last.questions.map(q=>({type:'check',conceptId:'guided-mastery',objectiveId:`${S.subject}-ch${ch.number}-guided-mastery`,prompt:cleanStudentText(q),guidance:'Answer in 1-2 sentences.',answer:last.more||'Use the chapter vocabulary accurately and explain the evidence.'}))}let qs=[];(ch.sections||[]).slice(0,6).forEach((s,i)=>{let meta=sectionMeta(ch,s,i),activity=alignedActivity(meta,ch);qs.push({type:'check',conceptId:meta.conceptId,objectiveId:meta.learningObjectiveId,prompt:`For ${meta.title}: ${activity.question}`,guidance:activity.apply,answer:activity.answer})});if((ch.vocabulary||[])[0]){let i=termInfo(ch.vocabulary[0]);qs.unshift({type:'definition',conceptId:`term-${slugText(i.term)}`,objectiveId:`${S.subject}-ch${ch.number}-term-${slugText(i.term)}`,prompt:`What does ${i.term} mean in this chapter? Give one matching example.`,guidance:'Define the word, then give one chapter example.',answer:`${i.definition} Example: ${i.example}`})}qs.push(chapterScenarioQuestion(ch));let seen=new Set();return qs.filter(q=>{let key=slugText(q.prompt);if(seen.has(key))return false;seen.add(key);return true}).slice(0,8)}
function saveCheck(i,v){let key=`${S.subject}-${S.chapter}-check`;saved[key]=saved[key]||{};saved[key][i]=v;save()}
function revealAnswer(btn,a){btn.parentElement.querySelector('.fb').innerHTML=`<div class="feedback"><strong>Use this to check your thinking:</strong> ${esc(a)}</div>`}
function showGlossary(){S.view='glossary';render()}function glossary(){let c=course();let all=[];c.chapters.forEach(ch=>ch.vocabulary.forEach(v=>all.push({...v,ch:ch.number})));Object.keys(TERM_DEFS[S.subject]||{}).forEach(term=>all.push({term,ch:'guide'}));let seen=new Set();all=all.filter(v=>{let k=v.term.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>a.term.localeCompare(b.term));return `<div class="wrap"><div class="card"><h1>${esc(c.name)} Glossary</h1><input style="width:100%;padding:12px;border:1px solid var(--line);border-radius:10px" placeholder="Search terms" oninput="filterGlossary(this.value)"><div class="alpha-row no-print">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<button class="secondary" onclick="filterGlossary('${l.toLowerCase()}')">${l}</button>`).join('')}</div><div id="glist" class="glossary-grid" style="margin-top:16px">${all.map(v=>{let info=termInfo(v);return `<button class="glossary-item" data-term="${esc(v.term.toLowerCase())}" onclick='globalTerm(${JSON.stringify(v.term)})'><strong>${esc(info.term)}</strong><div class="muted">${v.ch==='guide'?'Chapter guide':'Chapter '+v.ch}</div><div class="muted">${esc(info.definition.slice(0,110))}${info.definition.length>110?'…':''}</div></button>`}).join('')}</div></div></div>`}
function filterGlossary(v){v=v.toLowerCase();document.querySelectorAll('#glist .glossary-item').forEach(x=>x.style.display=x.dataset.term.includes(v)?'block':'none')}
function globalTerm(term){for(let c of Object.values(S.data))for(let ch of c.chapters){let v=ch.vocabulary.find(x=>x.term===term);if(v){let old=S.subject;S.subject=c.id||old;let info=termInfo(v);S.subject=old;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="document.getElementById('modal').remove()">✕</button><h2>${esc(info.term)}</h2><p>${esc(info.definition)}</p><p class="muted">Found in ${esc(c.name)} Chapter ${ch.number}</p><h3>Example</h3><p>${esc(info.example)}</p><h3>Context</h3><p>${esc(info.context)}</p></div></div>`);return}}let info=termInfo({term});document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="document.getElementById('modal').remove()">✕</button><h2>${esc(info.term)}</h2><p>${esc(info.definition)}</p><h3>Example</h3><p>${esc(info.example)}</p></div></div>`)}
function semesterQuestion(q){let ch=course().chapters.find(x=>x.number===q.chapter),prompt=clearPromptText(q.prompt);if(prompt&&prompt.length>25&&!/Which term best matches this meaning/i.test(prompt))return prompt;if(ch){let term=termInfo((ch.vocabulary||[])[0]||{term:'chapter idea'});if(S.subject==='math')return `Chapter ${ch.number}: Use ${term.term} to solve, graph, model, or justify one idea from ${ch.title}.`;return S.subject==='biology'?`Chapter ${ch.number}: Explain ${term.term} using one example from ${ch.title}.`:`Chapter ${ch.number}: Use ${term.term} to explain one place, region, or pattern from ${ch.title}.`}return `Chapter ${q.chapter}: Name one important idea and explain it with an example.`}
function semesterView(n){S.view='semester';S.sem=n;navigate()}function semester(){let c=course(),sem=c.semesters[String(S.sem)];return `<div class="wrap"><div class="card"><div class="eyebrow">${esc(c.name)}</div><h1>Semester ${S.sem} review & final</h1><p>Chapters ${sem.chapters.join(', ')}</p><div class="actions"><button class="primary" onclick="exportSemester(false)">Export practice review PDF</button><button class="secondary" onclick="exportSemester(true)">Export final PDF</button></div>${sem.review.slice(0,20).map((q,i)=>`<div class="worksheet-item"><strong>${i+1}. ${esc(semesterQuestion(q))}</strong></div>`).join('')}</div></div>`}
function parentView(){S.view='parent';navigate()}function parentPage(){let rows=[];for(let [id,c] of Object.entries(S.data)){for(let ch of c.chapters){rows.push(`<tr><td>${esc(c.name)}</td><td>${ch.number}</td><td>${esc(ch.title)}</td><td>${ch.vocabulary.length}</td><td>${ch.sections.length}</td><td>${worksheetItems(ch).length}</td><td>${saved[id+'-'+ch.number+'-done']?'✓':'—'}</td></tr>`)}}return `<div class="wrap">${parentProgressTools()}${parentPortfolioTools()}${parentPacing()}${week2Parent()}${curriculumCompleteness()}<div class="card"><h1>Parent curriculum inspector</h1><p class="muted">Source files and completeness are visible here; Liam's normal screens stay clean.</p><table style="width:100%;border-collapse:collapse"><thead><tr><th>Course</th><th>Ch.</th><th>Title</th><th>Terms</th><th>Sections</th><th>Worksheet items</th><th>Done</th></tr></thead><tbody>${rows.join('')}</tbody></table></div></div>`}
function parentProgressTools(){return `<div class="card progress-tools"><div class="eyebrow">Progress safety</div><h1>Liam progress backup</h1><p class="muted">Progress is saved locally on Liam’s computer using a versioned schema. App updates do not clear this record.</p><div class="actions"><button class="primary" onclick="exportProgressBackup()">Export All Liam Progress</button><button class="secondary" onclick="document.getElementById('progress-import').click()">Import Progress Backup</button><button class="secondary" onclick="exportProgressReport()">Print / Export Progress Report</button><input id="progress-import" class="hidden-file" type="file" accept="application/json,.json" onchange="importProgressBackup(this.files&&this.files[0]);this.value=''"></div><p class="muted">Schema v${saved.__schemaVersion||PROGRESS_SCHEMA_VERSION} · Last saved: ${esc(saved.__updatedAt||'not yet saved')}</p></div>`}
function parentPortfolioTools(){let weeks=Object.values(WEEKLY_PORTFOLIOS);let w=saved['portfolio-week']||2,checks=subjectIds().map(id=>`<label><input type="checkbox" id="portfolio-${id}" ${subjectHasWeekWork(id,w)?'checked':''}> ${subjectIcon(id)} ${esc(subjectLabel(id))}</label>`).join('');return `<div class="card portfolio-tools"><div class="eyebrow">California documentation</div><h1>Weekly Learning Portfolio</h1><p class="muted">Generates a local PDF from Liam DeVries's saved work. It documents curriculum alignment and student evidence without claiming official teacher evaluation.</p><div class="portfolio-form"><label>Week<select onchange="saved['portfolio-week']=Number(this.value);save();render(false)">${weeks.map(x=>`<option value="${x.week}" ${x.week==w?'selected':''}>${esc(x.label)} · ${esc(x.range)}</option>`).join('')}</select></label>${checks}<label>Student reflection<textarea data-autosave-key="portfolio-week-${w}-reflection" placeholder="This week I learned...">${esc(saved[`portfolio-week-${w}-reflection`]||'')}</textarea></label><label>Parent notes<textarea data-autosave-key="portfolio-week-${w}-parent-notes" placeholder="Optional parent notes for this report.">${esc(saved[`portfolio-week-${w}-parent-notes`]||'')}</textarea></label></div><div class="actions"><button class="primary" onclick="previewWeeklyPortfolio()">Preview Portfolio</button><button class="primary" onclick="downloadWeeklyPortfolio()">Download PDF</button><button class="secondary" onclick="printWeeklyPortfolio()">Print</button><button class="secondary" onclick="downloadMonthlyPortfolio()">Generate Monthly Portfolio</button><button class="secondary" onclick="downloadSemesterPortfolio(1)">Generate Semester Portfolio</button><button class="secondary" onclick="downloadCoursePortfolio()">Generate Complete Course Portfolio</button></div><h2>Portfolio archive</h2><div class="portfolio-archive">${weeks.map(x=>`<div><strong>${esc(x.label)}</strong> <span class="muted">${esc(x.range)}</span> <button class="secondary" onclick="saved['portfolio-week']=${x.week};save();previewWeeklyPortfolio()">Preview</button> <button class="secondary" onclick="saved['portfolio-week']=${x.week};save();downloadWeeklyPortfolio()">PDF</button></div>`).join('')}</div><div id="portfolio-preview" class="portfolio-preview"></div></div>`}
function parentPacing(){let sums=subjectIds().map(id=>pacingSummary(id)).filter(Boolean);if(!sums.length)return '';let issues=sums.flatMap(s=>s.validations||[]);return `<div class="card pacing-panel"><div class="eyebrow">Parent pacing</div><h1>Calendar-based subject pacing</h1><p class="muted">Uses Liam’s 2026-2027 school year, breaks, subject days, mastery rules, and protected semester review/final days. Skipped or no-school days recalculate quietly; they do not create catch-up debt.</p><div class="grid">${sums.map(pacingCard).join('')}</div><h2>Validation</h2><div class="validation-list">${issues.length?issues.map(x=>`<p class="warn">⚠ ${esc(x)}</p>`).join(''):'<p class="ok">✓ No pacing validation issues detected.</p>'}</div></div>`}
function pacingCard(sum){let subject=subjectLabel(sum.subject),ch=sum.current,plan=sum.currentPlan||{},upcoming=sum.plans.filter(p=>p.type==='chapter').slice(0,5),reserved=sum.plans.filter(p=>p.status==='reserved').length,chapterType=sum.subject==='biology'?window.LiamPacing.chapterComplexity(ch,'biology'):sum.subject==='math'?'Math concept day':'Weekly chapter';return `<section class="pacing-card"><h2>${subjectIcon(sum.subject)} ${esc(subject)}</h2><p><strong>Current:</strong> Chapter ${ch.number} — ${esc(ch.title)}</p><p><strong>Status:</strong> ${esc(sum.status)}</p><p><strong>Chapter type:</strong> ${esc(chapterType)}</p><p><strong>Mastery:</strong> ${sum.mastery||0}%</p><p><strong>Semester 1 target:</strong> ${esc(sum.targets[1])}</p><p><strong>Semester 2 target:</strong> ${esc(sum.targets[2])}</p><p><strong>Available subject sessions:</strong> ${sum.subjectDates.length}</p><p><strong>Reserved review/final days:</strong> ${reserved}</p><p><strong>Next action:</strong> ${sum.subject==='biology'&&sum.mastery>0&&sum.mastery<80?'Targeted review before advancing':plan.type==='chapter'?`Continue ${plan.part||'chapter'}`:'Review/final preparation'}</p><details><summary>Upcoming paced days</summary>${upcoming.map(p=>`<p>${esc(p.date)} — Chapter ${p.chapter}: ${esc(p.title)} ${p.part?`(${esc(p.part)})`:''}</p>`).join('')}</details></section>`}
function week2Parent(){return `<div class="card"><div class="eyebrow">Week 2 parent view</div><h1>Separate mastery tracking</h1><div class="grid">${week2ParentCard('biology',2)}${week2ParentCard('geography',2)}</div></div>`}
function week2ParentCard(subject,n){let c=S.data[subject],ch=c?.chapters.find(x=>x.number===n),guide=WEEK2_GUIDES[subject]?.[n];if(!guide||!ch)return '';return `<section class="inventory-course"><h2>${esc(c.name)} Week 2</h2><p class="muted">Chapter ${n}: ${esc(ch.title)}</p>${guide.mastery.map((m,i)=>{let done=saved[`${subject}-${n}-guide-done-${Math.min(i,guide.steps.length-1)}`];return `<p>${done?'✓':'○'} ${esc(m)}</p>`}).join('')}<p class="muted">Evidence records: ${Object.keys(saved).filter(k=>k.startsWith(`${subject}-${n}-evidence-`)).length}</p></section>`}
function curriculumCompleteness(){let inv=window.__LIAM_CURRICULUM_INVENTORY__;if(!inv)return `<div class="card"><h1>Course Completeness</h1><p class="muted">Inventory has not been generated yet. Run npm run validate-curriculum.</p></div>`;let cards=subjectIds().map(id=>inv[id]).filter(Boolean).map(courseInventoryCard).join('');return `<div class="card"><h1>Course Completeness</h1><p class="muted">Tracks source files, processed curriculum data, and chapters actually rendered in the website. Source hashes are stored for safe future updates.</p><div class="grid">${cards}</div><h2>Supplemental files</h2><div class="inventory-list">${(inv.supplemental||[]).map(item=>`<article><strong>${esc(item.name)}</strong><span class="${item.status==='SOURCE_FOUND'?'ok':'bad'}">${esc(item.status)}</span><small>${esc(item.file||'')}</small><code>${item.hash?esc(item.hash.slice(0,16))+'...':'no hash'}</code></article>`).join('')}</div></div>`}
function courseInventoryCard(course){return `<section class="inventory-course"><h2>${esc(course.label)}</h2><p>${course.availableSourceChapters} source chapters · ${course.parsed} parsed · ${course.rendered} rendered · ${course.validated} validated · ${course.intentionallyUnavailable||0} unavailable · ${course.unaccounted} unaccounted</p><div class="inventory-list">${course.chapters.map(row=>`<article><strong>Chapter ${row.chapter}: ${esc(row.title)}</strong><span>${row.statuses.map(status=>`<b class="${status==='FAILED'||status==='MISSING'?'bad':status==='UNAVAILABLE'?'warn':'ok'}">${esc(status)}</b>`).join(' ')}</span><small>${esc(row.sourceFile||row.note||'')}</small><code>${row.hash?esc(row.hash.slice(0,16))+'...':'no hash'}</code></article>`).join('')}</div></section>`}
function subjectHasWeekWork(subject,weekNum){let week=WEEKLY_PORTFOLIOS[weekNum]||WEEKLY_PORTFOLIOS[2],n=week.chapters[subject]||Number(saved[subject+'-current']||S.data?.[subject]?.chapters?.[0]?.number||1),guide=WEEK2_GUIDES[subject]?.[n];return !!(guide&&guide.steps.some((_,i)=>saved[`${subject}-${n}-guide-done-${i}`]))||Object.keys(saved[`${subject}-${n}-worksheet`]||{}).some(k=>String(saved[`${subject}-${n}-worksheet`][k]||'').trim())||Object.keys(saved[`${subject}-${n}-check`]||{}).some(k=>String(saved[`${subject}-${n}-check`][k]||'').trim())}
function selectedPortfolioSubjects(){return subjectIds().filter(id=>{let el=document.getElementById('portfolio-'+id);return !el||el.checked})}
function weeklyPortfolioData(weekNum,subjects){
let week=WEEKLY_PORTFOLIOS[weekNum]||WEEKLY_PORTFOLIOS[2];
let data={student:STUDENT,schoolYear:'2026-2027',week,generated:new Date().toLocaleString(),subjects:[],reflection:saved[`portfolio-week-${week.week}-reflection`]||'',parentNotes:saved[`portfolio-week-${week.week}-parent-notes`]||''};
for(const subject of subjects){
let chapterNum=week.chapters[subject],guide=WEEK2_GUIDES[subject]?.[chapterNum],courseData=S.data[subject],chapter=courseData?.chapters.find(ch=>ch.number===chapterNum);
if(!chapter){chapterNum=Number(saved[subject+'-current']||courseData?.chapters?.[0]?.number||1);chapter=courseData?.chapters.find(ch=>ch.number===chapterNum)}
if(!chapter)continue;
let item={id:subject,name:courseData.name,chapter,guide,completed:[],objectives:[],interactive:[],responses:[],assessments:[],evidence:[],mastery:[],standards:[]};
if(!guide){
let progress=Number(saved[`${subject}-${chapterNum}-progress`]||0);
if(progress>0||saved[`${subject}-${chapterNum}-done`]){
item.completed.push({title:`Chapter ${chapterNum} learning progress`,date:saved.__updatedAt||'',step:{k:(chapter.vocabulary||[]).map(v=>v.term).join(' ')}});
item.objectives.push({text:`Continue Chapter ${chapterNum}: ${chapter.title}`,status:saved[`${subject}-${chapterNum}-done`]?'Completed':'In Progress'});
item.mastery.push({concept:chapter.title,status:saved[`${subject}-${chapterNum}-done`]?'Completed':'Developing',evidence:'saved local progress'});
}
}
if(guide){
guide.steps.forEach((step,i)=>{
let done=!!saved[`${subject}-${chapterNum}-guide-done-${i}`];
let apply=saved[`${subject}-${chapterNum}-guide-${i}-apply`]||'';
let evidenceDate=saved[`${subject}-${chapterNum}-evidence-${i}`]||'';
if(done){
let status=(apply||step.sort||step.questions)?'Mastered':'Completed';
let evidence=step.sort?'interactive sorting':apply?'written response':step.questions?'mastery check':'completed lesson';
item.completed.push({title:step.t,date:evidenceDate||saved.__updatedAt||'',step});
item.objectives.push({text:step.t,status});
item.mastery.push({concept:step.t,status:status==='Completed'?'Developing':status,evidence});
item.evidence.push({title:step.t,type:step.sort?'Interactive activity':step.questions?'Knowledge check':'Learning block',date:evidenceDate});
}
if(done&&step.sort){
let p=(saved[`${subject}-${chapterNum}-activity-${step.sort.id}-state`]||{}).placements||saved[`${subject}-${chapterNum}-sort-${step.sort.id}-placements`]||{};
let groups=step.sort.groups.map(g=>({label:g.label,description:g.description,items:step.sort.items.filter(x=>p[x.id]===g.id).map(x=>x.label)}));
let score=step.sort.items.filter(x=>p[x.id]===x.correctGroupId).length;
item.interactive.push({title:step.t,prompt:step.sort.prompt,groups,score,total:step.sort.items.length});
}
if(done&&apply)item.responses.push({activity:step.t,prompt:step.apply||'Application response',response:apply});
if(done&&step.questions){
let answers=step.questions.map((q,qi)=>({question:q,response:saved[`${subject}-${chapterNum}-guide-${i}-q${qi}`]||''}));
let answered=answers.filter(a=>a.response.trim()).length;
item.assessments.push({title:step.t,attempt:1,score:answered,total:answers.length,percentage:answers.length?Math.round(answered/answers.length*100):0,status:answered===answers.length?'Completed':'In Progress',answers});
}
});
}
let wvals=saved[`${subject}-${chapterNum}-worksheet`]||{};
let wanswers=Object.keys(wvals).filter(k=>String(wvals[k]||'').trim()).map(k=>({question:Number(k)+1,response:wvals[k]}));
if(wanswers.length){
item.evidence.push({title:`${courseData.name} Chapter ${chapterNum} worksheet responses`,type:'Worksheet',date:saved.__updatedAt||''});
item.responses.push(...wanswers.slice(0,6).map(a=>({activity:'Worksheet',prompt:`Worksheet item ${a.question}`,response:a.response})));
}
let cvals=saved[`${subject}-${chapterNum}-check`]||{};
let canswers=Object.keys(cvals).filter(k=>String(cvals[k]||'').trim()).map(k=>({question:Number(k)+1,response:cvals[k]}));
if(canswers.length){
item.assessments.push({title:`${courseData.name} Chapter ${chapterNum} knowledge check`,attempt:1,score:canswers.length,total:knowledgeItems(chapter).length,percentage:Math.round(canswers.length/Math.max(1,knowledgeItems(chapter).length)*100),status:'Completed responses saved',answers:canswers.map(a=>({question:`Knowledge check item ${a.question}`,response:a.response}))});
}
item.standards=portfolioStandards(subject,item);
if(item.completed.length||item.responses.length||item.assessments.length||item.interactive.length)data.subjects.push(item);
}
return data;
}
function portfolioStandards(subject,item){if(!item.completed.length)return [];if(subject==='biology'){let text=item.completed.map(x=>x.step.k+' '+x.title).join(' ').toLowerCase(),out=[];if(/food|energy|matter|trophic|ecosystem|producer|consumer|decomposer/.test(text))out.push({...CA_STANDARDS.biology['HS-LS2-4'],learningTarget:'Use ecosystem evidence to explain matter cycling and energy flow.',evidence:item.interactive[0]?.title||item.completed[0].title});if(/sphere|carbon|matter cycles/.test(text))out.push({...CA_STANDARDS.biology['HS-LS2-5'],learningTarget:'Use system models to explain cycling among Earth systems.',evidence:item.completed.find(x=>/matter|cycle/i.test(x.title))?.title||item.completed[0].title});return out}if(subject==='math'){let standards=item.chapter?.standards||[];return standards.slice(0,2).map(st=>({...st,subject:'Integrated Math I',type:'Math I Standard Alignment',verified:true,learningTarget:st.shortDescription,evidence:item.completed[0]?.title||item.responses[0]?.activity||'completed math work'}))}return [{...CA_STANDARDS.geography['HSS-FRAMEWORK-GEO-LITERACY'],learningTarget:'Analyze Earth systems, physical processes, and place-based evidence using geographic reasoning.',evidence:item.completed[0]?.title||'completed geography work'}]}
function portfolioLines(data){let subjectNames=data.subjects.map(s=>s.name).join(', ')||'No completed subjects';let lines=['LIAM LEARNING','WEEKLY LEARNING PORTFOLIO','','Student: Liam DeVries','Grade: 9','School Year: '+data.schoolYear,'Week: '+data.week.label,'Reporting Period: '+data.week.range,'Subjects: '+subjectNames,'Generated: '+data.generated,'','This app-generated portfolio documents saved curriculum work, student responses, assessment records, and standards/framework alignment. Certificated teacher evaluation is not claimed unless added separately.','\f','WEEK AT A GLANCE'];if(!data.subjects.length)lines.push('No completed subject work was found in saved progress for this selected week.');data.subjects.forEach(s=>{lines.push('',s.name.toUpperCase(),`Chapter ${s.chapter.number} - ${s.chapter.title}`,'Liam learned to:');if(s.completed.length)s.completed.forEach(x=>lines.push('- '+x.title));else lines.push('- No completed blocks saved for this week.');lines.push('','LEARNING OBJECTIVES ADDRESSED');s.objectives.forEach((o,i)=>lines.push(`${i+1}. ${o.text} - ${o.status}`));lines.push('','CALIFORNIA STANDARDS ALIGNMENT');if(s.standards.length)s.standards.forEach(st=>{lines.push(`${st.id} (${st.authority})`,st.shortDescription,'Learning target: '+st.learningTarget,'Evidence this week: '+st.evidence,'Source: '+st.sourceUrl,'Alignment type: '+st.type,'')});else lines.push('No direct standard/framework alignment is reported because no completed evidence was found.');lines.push('ACTUAL STUDENT WORK');s.interactive.forEach(a=>{lines.push(`Activity: ${a.title}`,a.prompt);a.groups.forEach(g=>lines.push(`${g.label}: ${g.items.join(', ')||'none saved'}`));lines.push(`Result: ${a.score} / ${a.total}`,'')});s.responses.forEach(r=>{lines.push('Activity: '+r.activity,'Question: '+r.prompt,"Liam's Response:",r.response,'')});lines.push('KNOWLEDGE CHECK / ASSESSMENT RESULTS');if(s.assessments.length)s.assessments.forEach(a=>{lines.push(a.title,`Attempt: ${a.attempt}`,`Score/Responses: ${a.score} / ${a.total}`,`Percentage: ${a.percentage}%`,`Status: ${a.status}`);a.answers.slice(0,6).forEach(ans=>lines.push('Question: '+ans.question,"Liam's answer: "+(ans.response||'(blank)')));lines.push('')});else lines.push('No knowledge-check responses saved for this subject this week.');lines.push('EVIDENCE OF LEARNING');s.evidence.forEach((e,i)=>lines.push(`Evidence Item ${i+1}: ${e.title} (${e.type})${e.date?' - '+e.date:''}`));lines.push('','MASTERY SUMMARY','CONCEPT | STATUS | EVIDENCE');s.mastery.forEach(m=>lines.push(`${m.concept} | ${m.status} | ${m.evidence}`));lines.push('','WORK COMPLETED');s.completed.forEach(x=>lines.push(`✓ ${x.title}${x.date?' - '+x.date:''}`));lines.push('','ENGAGEMENT / ACTIVITY LOG',`Student: Liam DeVries`,`Subject: ${s.name}`,`Instructional activities completed: ${s.completed.length}`,`Assessments completed: ${s.assessments.length}`,`Written responses: ${s.responses.length}`,`Interactive activities: ${s.interactive.length}`,'\f')});lines.push('STUDENT REFLECTION');lines.push(data.reflection||'No student reflection entered.');lines.push('','PARENT NOTES');lines.push(data.parentNotes||'No parent notes entered.');lines.push('','CERTIFICATED TEACHER REVIEW','','Teacher: _______________________________','','Date Reviewed: __________________________','','Evaluation / Notes:','','________________________________________________','','________________________________________________','','Signature / Initials: ____________________');return lines}
function portfolioFileName(data,label='Learning_Portfolio'){return `Liam_DeVries_Week_${String(data.week.week).padStart(2,'0')}_${label}_${data.week.end}.pdf`}
function previewWeeklyPortfolio(){let data=weeklyPortfolioData(Number(saved['portfolio-week']||2),selectedPortfolioSubjects()),lines=portfolioLines(data);let host=document.getElementById('portfolio-preview');if(host)host.innerHTML=`<h2>Portfolio preview</h2><pre>${esc(lines.filter(x=>x!=='\f').join('\n'))}</pre>`}
function downloadWeeklyPortfolio(){let data=weeklyPortfolioData(Number(saved['portfolio-week']||2),selectedPortfolioSubjects());download(pdfBlobWithFooter(portfolioLines(data),{week:data.week.week}),portfolioFileName(data))}
function printWeeklyPortfolio(){previewWeeklyPortfolio();let host=document.getElementById('portfolio-preview');let w=window.open('','_blank','noopener');if(!w)return;w.document.write(`<title>Liam DeVries Weekly Portfolio</title><style>body{font-family:Arial,sans-serif;margin:36px;line-height:1.45}pre{white-space:pre-wrap} @page{margin:0.6in}</style><pre>${esc((host?.innerText||'').replace(/^Portfolio preview\\n/,''))}</pre>`);w.document.close();w.print()}
function downloadMonthlyPortfolio(){let data=weeklyPortfolioData(2,selectedPortfolioSubjects());download(pdfBlobWithFooter(['LIAM LEARNING','MONTHLY LEARNING PORTFOLIO','Student: Liam DeVries','Grade: 9','School Year: 2026-2027','','Included weeks: Week 2',...portfolioLines(data).slice(10)],{week:2}),`Liam_DeVries_Monthly_Learning_Portfolio_${data.week.end}.pdf`)}
function downloadSemesterPortfolio(n){let data=weeklyPortfolioData(2,selectedPortfolioSubjects());download(pdfBlobWithFooter(['LIAM LEARNING',`SEMESTER ${n} LEARNING PORTFOLIO`,'Student: Liam DeVries','Grade: 9','School Year: 2026-2027','','This semester portfolio compiles saved weekly evidence currently available in the app.','',...portfolioLines(data).slice(10)],{week:2}),`Liam_DeVries_Semester_${n}_Learning_Portfolio_${data.week.end}.pdf`)}
function downloadCoursePortfolio(){let data=weeklyPortfolioData(2,selectedPortfolioSubjects());download(pdfBlobWithFooter(['LIAM LEARNING','COMPLETE COURSE PORTFOLIO','Student: Liam DeVries','Grade: 9','School Year: 2026-2027','','This complete-course portfolio compiles saved evidence currently available in local progress.','',...portfolioLines(data).slice(10)],{week:2}),`Liam_DeVries_Complete_Course_Portfolio_${data.week.end}.pdf`)}
// Reusable academic PDF renderer for worksheets, reports, portfolios, and semester exports.
function pdfClean(value){return String(value??'').normalize('NFKD').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[\u2013\u2014]/g,'-').replace(/\u00A0/g,' ').replace(/[^\x09\x0A\x0D\x20-\x7E\u2192\u2022\u2713]/g,'')}
function pdfHex(value){let s=pdfClean(value),hex='FEFF';for(let ch of s){let c=ch.codePointAt(0);if(c>65535)c=63;hex+=(c>>8&255).toString(16).toUpperCase().padStart(2,'0')+(c&255).toString(16).toUpperCase().padStart(2,'0')}return `<${hex}>`}
function pdfLineWidth(size){return Math.max(38,Math.floor(490/(size*.48)))}
function pdfWrap(text,size=10,maxChars=0){let out=[];String(text??'').split(/\n/).forEach(line=>{line=pdfClean(line).replace(/\s+/g,' ').trim();if(!line){out.push('');return}let limit=maxChars||pdfLineWidth(size);while(line.length>limit){let cut=line.lastIndexOf(' ',limit);if(cut<24)cut=limit;out.push(line.slice(0,cut).trim());line=line.slice(cut).trim()}out.push(line)});return out}
function pdfTextCmd(x,y,text,size=10,font='F1',gray=0){return `BT ${gray} g /${font} ${size} Tf ${x} ${y} Td ${pdfHex(text)} Tj ET\n`}
